window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["31"]={"https://www.gov.uk/foreign-travel-advice/albania":{"r":"govuk","at":"2026-11-17T16:16Z","sha":"de05ece3ea666de7c2023cea7b8e00625eb680f1e9bd24dd496a81c4581d2497","read":"https://www.gov.uk/api/content/foreign-travel-advice/albania","bytes":58396,"x":"fulltext v1","title":"Albania travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-01-22T00:00:00+00:00","mod":"2026-10-15T16:44:54+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Demonstrations"]},{"k":"p","s":["Demonstrations have been held in central Tirana, with some reported incidents of violence and property damage."]},{"k":"p","s":["You should:"]},{"k":"li","s":["check local media for the latest information"]},{"k":"li","s":["stay away from any demonstrations, large-scale gatherings or political rallies"]},{"k":"li","s":["follow the advice of the local authorities"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/albania/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of the current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Albania set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Albanian Embassy in the UK","https://ambasadat.gov.al/united-kingdom/en"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Your passport must have an ‘expiry date’ at least 3 months after the day you plan to leave Albania."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can visit Albania without a visa for up to 90 days in a 180-day period, for tourism or business."]},{"k":"p","s":["If you want to stay longer than 90 days, you must ",["apply in advance for a long-stay visa","https://e-visa.al/apply"]," or ",["apply for a residence permit from within Albania","https://e-albania.al/eAlbaniaServices/UseService.aspx?service_code=15308"],"."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To enter Albania, you must have a certificate to prove you’ve had a yellow fever vaccination if you’re coming from a ",["country listed as a transmission risk","https://nathnacyfzone.org.uk/factsheet/65/countries-with-risk-of-yellow-fever-transmission"],"."]},{"k":"p","s":["For full details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Albania guide","https://travelhealthpro.org.uk/country/2/albania#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of Albania. You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Albania"]},{"k":"p","s":["Terrorist attacks in Albania cannot be ruled out."]},{"k":"p","s":["Attacks could be indiscriminate including in places visited by foreigners. Stay aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Relations between the majority Muslim population and other ethnic groups in Albania are generally good. The expression of extremist or anti-western views is very rare."]},{"k":"p","s":["Political and other demonstrations have been held in central Tirana, with some reported incidents of violence. Demonstrations can cause traffic diversions and other disruption. Demonstrations could happen elsewhere, and may take place outside the capital city."]},{"k":"p","s":["You should:"]},{"k":"li","s":["check local media for the latest information"]},{"k":"li","s":["avoid any demonstrations, large-scale gatherings or political rallies"]},{"k":"li","s":["follow the advice of the local authorities"]},{"k":"h","s":["Crime"]},{"k":"p","s":["There is crime and violence in some areas, but reports of crime targeting foreigners are rare. There have been occasional shootings and small explosions related to internal disputes over criminal, business or political interests."]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["Take sensible precautions to protect yourself from street crime, particularly in larger cities and late at night."]},{"k":"p","s":["Watch out for pickpockets and bag thieves in tourist areas, on buses and trains and major public transport hubs, including airports."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Illegal drugs"]},{"k":"p","s":["Penalties for drug-related crimes are severe."]},{"k":"p","s":["You should expect a long jail sentence and heavy fines for possessing, using or smuggling illegal drugs, including when transiting through the airport."]},{"k":"p","s":["Possession of illegal drugs could result in a prison sentence of 5 to 10 years. The penalty for supplying drugs is up to 15 years in prison."]},{"k":"p","s":["Airports in Albania have excellent technology and security for detecting illegal items, including cannabis. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["Being arrested"]},{"k":"p","s":["The Albanian authorities do not always inform the British Embassy when British nationals have been arrested. If you are detained, you may insist on your right to contact the ",["British Embassy in Tirana","https://www.gov.uk/world/organisations/british-embassy-tirana"],"."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex relationships are legal in Albania. Anti-discrimination and anti-hate-crime legislation is in place. Tirana has several gay-friendly bars and a number of LGBT+ support groups."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"hs","s":["Water sports and swimming safety"]},{"k":"p","s":["There are some local press reports that jet skis and boats being rented along the coasts may lack adequate safety precautions and equipment."]},{"k":"p","s":["If you are considering taking part in water sports activities, do so through a licensed water sports centre and make sure paperwork is completed before starting the activity."]},{"k":"p","s":["See ",["watersports safety abroad","https://www.rospa.com/leisure-water-safety/water/advice/watersports-abroad"]," from the Royal Society for the Prevention of Accidents."]},{"k":"p","s":["Take note of warning signs, follow instructions from lifeguards and observe the flag indicators on beaches. Take local advice if jellyfish or urchins are present."]},{"k":"p","s":["The ",["2023 European Environment Agency report","https://www.eea.europa.eu/en/countries/cooperating-countries/albania"]," noted that a small number of beaches are polluted because of inadequate sewage disposal and treatment."]},{"k":"p","s":["See ",["water safety on holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Albania, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"]," and check the ",["rules of the road in the RAC’s Albania guide","https://www.rac.co.uk/drive/travel/country/albania/"],". The guide lists driving regulations and other legal requirements you need to be aware of."]},{"k":"p","s":["You may find it useful to have a ",["1968 international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," as well as your UK licence. The 1949 IDP is not accepted any more. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["You must carry a ",["green card","https://www.gov.uk/vehicle-insurance/driving-abroad"]," as proof of vehicle insurance to drive your car in Albania. If you’re planning to hire a car, check with your car hire company for information on their requirements before you travel."]},{"k":"p","s":["Check if you need a ",["UK sticker to drive your car outside the UK","https://www.gov.uk/displaying-number-plates/flags-identifiers-and-stickers"],"."]},{"k":"p","s":["If you stay longer than one year, or live in Albania, you will need to apply for an Albanian driving licence."]},{"k":"p","s":["To import a vehicle into Albania, make sure you have all the necessary papers on arrival at the border. Consult the Albanian Embassy in the UK before you leave. The British Embassy will be unable to help anyone attempting to bring a vehicle into Albania without the correct paperwork."]},{"k":"hs","s":["Dangers of driving in Albania"]},{"k":"p","s":["Driving can be very hazardous and often aggressive and erratic. Deaths from road traffic accidents are amongst the highest in Europe. Police have taken some measures to decrease the number of accidents."]},{"k":"p","s":["Minor traffic disputes can quickly escalate, especially as some motorists could be armed. Avoid reacting to provocative behaviour by other road users."]},{"k":"p","s":["If you are involved in a traffic accident, even a minor one, remain at the scene until the police arrive. This will usually happen quite quickly in built-up areas. Failing to wait could result in charges under the Albanian Penal Code and you could get a fine."]},{"k":"hs","s":["Road conditions"]},{"k":"p","s":["Road surfaces are poor, especially in rural areas. If you are travelling at night, watch out for unmarked roadworks, potholes and vehicles without lights. Four-wheel drive vehicles are more practical on rural and minor roads."]},{"k":"p","s":["Power cuts can affect street lighting in towns and cities. Elsewhere, even on the major routes, there is no street lighting."]},{"k":"h","s":["Landmines"]},{"k":"p","s":["There are still unexploded landmines in some remote areas around hill towns on the northern border with Kosovo. Take care, particularly if hiking, and follow any warning signs. Do not walk on uncultivated land or step off the marked paths. If in doubt, seek local advice."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["There is a risk of earthquakes – tremors are common. Serious earthquakes are less frequent but do happen."]},{"k":"p","s":["The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"hs","s":["Flooding and snow"]},{"k":"p","s":["From December to February, severe weather may cause flooding, particularly in northern Albania. Heavy snowfall in mountainous areas can lead to disruption to transport and services. Monitor local and international media for the latest information."]},{"k":"hs","s":["Wildfires"]},{"k":"p","s":["Wildfires are common in Albania from April to October due to the dry and hot weather. Wildfires are highly dangerous and unpredictable. You should:"]},{"k":"li","s":["take care when visiting or driving through countryside"]},{"k":"li","s":["make sure cigarette ends are properly extinguished"]},{"k":"li","s":["not light fires or barbecues except in designated and marked areas"]},{"k":"li","s":["not leave any rubbish"]},{"k":"p","s":["Causing a wildfire or a forest fire is a criminal offence in Albania. Penalties could result from fines to imprisonment."]},{"k":"p","s":["Be cautious if you are in or near an area affected by wildfires. During the event of a wildfire, you should:"]},{"k":"li","s":["call the emergency services on 112"]},{"k":"li","s":["follow any advice from the local emergency services"]},{"k":"li","s":["contact your airline or travel operator who can assist you with return travel to the UK"]},{"k":"li","s":["if you need consular assistance call +355 4 223 4973/4/5 during ",["working hours","https://www.gov.uk/world/organisations/british-embassy-tirana/office/british-embassy"]," or +44 207 008 5000 out of hours"]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 127 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Albania","https://travelhealthpro.org.uk/country/2/albania#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face Albania","https://travelhealthpro.org.uk/country/2/albania"],"."]},{"k":"p","s":["Altitude sickness is a risk in parts of Albania. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"hs","s":["Air pollution"]},{"k":"p","s":["There can be high levels of air pollution in Albania. You can find further information and advice on air quality on the ",["World Health Organization (WHO)","https://www.who.int/airpollution/en/"]," website and check air quality levels on the ",["World Air Quality Index website","https://aqicn.org/map/europe/"],"."]},{"k":"hs","s":["Tap water and milk"]},{"k":"p","s":["Do not drink the tap water in Albania, as it may cause illness. Only drink bottled water. If you drink milk, make sure it is UHT (ultra high temperature) or pasteurised milk."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Albania"]},{"k":"p","s":["Medical and dental facilities, including accident and emergency facilities, are very poor, particularly outside Tirana. Make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment abroad, evacuation by air ambulance and repatriation."]},{"k":"p","s":["FCDO has a list of ",["list of medical providers in Albania","https://www.gov.uk/government/publications/albania-list-of-medical-facilities"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Albania"]},{"k":"p","s":["Ambulance: 127"]},{"k":"p","s":["Fire: 128"]},{"k":"p","s":["Police: 112"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Albania"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Albania"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Albania"]," in Albania"]},{"k":"li","s":["dealing with a ",["death in Albania","https://www.gov.uk/government/publications/albania-bereavement-guide"]]},{"k":"li","s":["being ",["arrested in Albania","https://www.gov.uk/government/publications/albania-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/albania/british-embassy-tirana"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/albania/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":14071,"change":"New information about demonstrations in Tirana ('Warnings and insurance' page)."},"https://www.gov.uk/foreign-travel-advice/colombia":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"4b640d43b55f31472793d3f79202161b81d177330a71101d0a007b89c6d1a5ae","read":"https://www.gov.uk/api/content/foreign-travel-advice/colombia","bytes":95374,"x":"fulltext v1","title":"Colombia travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-03-21T00:00:00+00:00","mod":"2026-10-30T00:40:46+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Temporary deployment of security forces in the city of Cucuta"]},{"k":"p","s":["On 29 October, President de la Espriella ordered the temporary deployment of security forces in the city of Cucuta. Further security measures are expected in the coming days. Travellers should plan ahead, follow advice of local authorities, and see the ‘Safety and security’ pages."]},{"k":"h","s":["Areas where FCDO advises against all but essential travel"]},{"k":"hs","s":["Colombia-Venezuela border and northern Colombia"]},{"k":"p","s":["FCDO advises against all but essential travel to:"]},{"k":"li","s":["all of Norte de Santander Department, including Cúcuta."]},{"k":"li","s":["all of Arauca Department"]},{"k":"li","s":["the municipality of Puerto Carreño in Vichada Department"]},{"k":"li","s":["within 5km of the rest of the border with Venezuela."]},{"k":"p","s":["FCDO currently advises against all travel to ",["Venezuela’s border regions with Colombia","https://www.gov.uk/foreign-travel-advice/venezuela"],". You should not use any of the Colombia-Venezuela land crossings."]},{"k":"hs","s":["Pacific coast and Colombia-Panama border"]},{"k":"p","s":["FCDO advises against all but essential travel to:"]},{"k":"li","s":["Chocó Department, except for the department capital Quibdó, the towns of Nuquí and Bahía Solano and Capurganá"]},{"k":"li","s":["the western part of Valle del Cauca Department, including Buenaventura"]},{"k":"li","s":["the municipality of Jamundí, Valle del Cauca"]},{"k":"li","s":["the South Pacific, Sanquianga and Telembi regions of Nariño Department"]},{"k":"li","s":["the southern part of Córdoba Department"]},{"k":"li","s":["the Urabá and Bajo Cauca regions of Antioquia Department"]},{"k":"li","s":["the southern part of Bolívar Department"]},{"k":"hs","s":["Central Colombia"]},{"k":"p","s":["FCDO advises against all but essential travel to:"]},{"k":"li","s":["all of Guaviare Department, except for the department capital San José del Guaviare"]},{"k":"li","s":["Cartagena del Chairá, San Vicente del Caguan, Puerto Rico, El Doncello, Paujil and La Montañita in Caquetá Department"]},{"k":"li","s":["the Ariari region of southern Meta, except for Caño Cristales"]},{"k":"p","s":["If travelling to the tourist site of Caño Cristales, travel by air from the town of La Macarena with a reputable tour company."]},{"k":"hs","s":["Colombia-Ecuador border and southern Colombia"]},{"k":"p","s":["FCDO advises against all but essential travel to within 5km of the border with Ecuador except for:"]},{"k":"li","s":["all of Cauca Department, except for the department capital Popayán"]},{"k":"li","s":["the border crossing on the Pan-American highway at the Puente Internacional de Rumichaca"]},{"k":"li","s":["the city of Ipiales in Nariño Department"]},{"k":"p","s":["FCDO advises against all but essential travel to Orito, San Miguel, Valle del Guamuez, Puerto Caicedo, Puerto Guzmán, Puerto Asis and Puerto Leguizamo in Putumayo Department."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/colombia/regional-risks"],"."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. If you have onward travel plans within the region, check travel advice for all destinations you plan to travel through. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://webarchive.nationalarchives.gov.uk/ukgwa/20260804150650mp_/https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://webarchive.nationalarchives.gov.uk/ukgwa/20260804150650mp_/https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://webarchive.nationalarchives.gov.uk/ukgwa/20260804150650mp_/https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://webarchive.nationalarchives.gov.uk/ukgwa/20260804150650mp_/https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://webarchive.nationalarchives.gov.uk/ukgwa/20260804150650mp_/https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://webarchive.nationalarchives.gov.uk/ukgwa/20260804150650mp_/https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://webarchive.nationalarchives.gov.uk/ukgwa/20260804150650mp_/https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://webarchive.nationalarchives.gov.uk/ukgwa/20260804150650mp_/https://www.gov.uk/foreign-travel-advice/colombia/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://webarchive.nationalarchives.gov.uk/ukgwa/20260804150650mp_/https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://webarchive.nationalarchives.gov.uk/ukgwa/20260804150650mp_/https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://webarchive.nationalarchives.gov.uk/ukgwa/20260804150650mp_/https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Colombia’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Colombia set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Colombian Embassy in the UK","https://reinounido.embajada.gov.co/"]," (for English choose ‘Ingles’ from the drop down menu)."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Colombia, your passport must be valid on entry. However, Colombian immigration authorities recommend your passport has an ‘expiry date’ at least 6 months after the date you plan to leave."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"hs","s":["British-Colombian dual nationals"]},{"k":"p","s":["If you’re a British-Colombian dual national, you must enter and leave Colombia using your Colombian passport and Colombian identification card (Cedula)."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can visit Colombia for up to 90 days without a visa for business or tourism, at the discretion of the Colombian immigration officer on arrival."]},{"k":"p","s":["You must be able to show an onward or return ticket valid within the 90-day period."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["Check the latest entry requirements and how to apply for a visa with the ",["Colombian Consulate General","https://londres.consulado.gov.co/"]," in London before you travel."]},{"k":"p","s":["If you have a Colombian visa with more than 90 days of validity, you must register the visa at a ",["Migración Colombia office","https://unidad-administrativa-especial-migracion-colombia.micolombiadigital.gov.co/cedula-de-extranjeria/agende-su-cita"]," (in Spanish) or ",["register the visa online","https://apps.migracioncolombia.gov.co/registro/public/formularioRegistro.jsf"]," (in Spanish) within 15 days of arrival in Colombia. If you do not register, you may get a fine."]},{"k":"p","s":["You may be able to extend your stay once you are in Colombia by up to 120 days by applying at the immigration office ",["Migración Colombia","https://unidad-administrativa-especial-migracion-colombia.micolombiadigital.gov.co/directorio-institucional/unidad-administrativa-especial-migracion-colombia"]," (in Spanish). As a visitor, you cannot remain in Colombia for more than 180 days in any 12-month period."]},{"k":"p","s":["If you overstay your visa, you could get a fine, or be deported at your own cost."]},{"k":"h","s":["Checks at border control"]},{"k":"p","s":["Colombian authorities advise that you can speed up your entry to the country by ",["completing the ‘Check-Mig’ form on Migración Colombia","https://apps.migracioncolombia.gov.co/pre-registro/en/DatosViaje"],", although this is not mandatory. You can complete the form between 72 hours and one hour before you travel to Colombia. You will receive a confirmation email that you will need to show to immigration officials when you arrive."]},{"k":"p","s":["Make sure you get your passport stamped."]},{"k":"p","s":["If you enter Colombia by land, sea or river, make sure the immigration authorities stamp your passport. If it is not stamped, you could get a fine when you leave. If the immigration office on the border is closed, go to the nearest office of ",["Migración Colombia","https://unidad-administrativa-especial-migracion-colombia.micolombiadigital.gov.co/directorio-institucional/unidad-administrativa-especial-migracion-colombia"]," (in Spanish)."]},{"k":"h","s":["Travelling with children"]},{"k":"p","s":["Children aged 17 and under who have resident status in Colombia and who are travelling on a British passport need a ",["notarised letter of permission from any non-accompanying parents or parent","https://www.migracioncolombia.gov.co/entidad/salida-de-menores-del-pais"]," (in Spanish). The letter must be authenticated by a notary or by a Colombian consulate. You can get more information from Migración Colombia (in Spanish) or by contacting the ",["Colombian Consulate in the UK","https://londres.consulado.gov.co/"]," (in Spanish)."]},{"k":"h","s":["San Andres Archipelago"]},{"k":"p","s":["If you’re travelling to the islands of San Andres, Providencia or Santa Catalina, you must buy a tourist card from the boarding gate, on the day of the flight. You do not need one if you’re staying less than 24 hours."]},{"k":"h","s":["Departure tax"]},{"k":"p","s":["Departure tax is usually included in the price of the airline ticket, but check with your airline."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To enter Colombia, you must have a certificate to prove you’ve had a yellow fever vaccination if you are arriving from certain countries with a transmission risk. You may also be asked to show it if you are travelling to areas in Colombia which are considered high risk. Carry your vaccination certificate at all times."]},{"k":"p","s":["For full details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Colombia guide","https://travelhealthpro.org.uk/country/53/colombia#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Colombia","https://www.dian.gov.co/"]," (in Spanish). You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking money into Colombia"]},{"k":"p","s":["You can bring up to 10,000 US dollars-worth of any currency into Colombia. You must declare anything above this amount with the ",["National Tax and Customs Directorate (DIAN)","https://www.dian.gov.co/Viajeros-y-Servicios-aduaneros/Paginas/Inicio.aspx"]," (in Spanish)."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Colombia"]},{"k":"p","s":["Terrorists are very likely to try to carry out attacks in Colombia."]},{"k":"hs","s":["Armed groups"]},{"k":"p","s":["Despite the landmark peace agreement between the government and the Revolutionary Armed Forces of Colombia (FARC) in 2016, many armed groups remain active throughout the country."]},{"k":"p","s":["These groups may attack with little or no warning. The focus is predominantly in areas where there are active illicit economies and narco-trafficking but attacks have historically targeted some tourist locations, including:"]},{"k":"li","s":["transportation hubs including airports"]},{"k":"li","s":["markets and shopping malls"]},{"k":"li","s":["local government facilities"]},{"k":"li","s":["hotels, clubs and restaurants"]},{"k":"li","s":["places of worship"]},{"k":"li","s":["parks and other public areas"]},{"k":"li","s":["major sporting and cultural events"]},{"k":"li","s":["educational institutions"]},{"k":"p","s":["Police and military personnel and installations are frequently targeted, including in large cities."]},{"k":"p","s":["Past methods of attack have included car bombs, grenade and drone attacks, and explosive devices left in buildings and on main roads. Stay alert and follow the advice of the local security authorities."]},{"k":"p","s":["Regularly reassess your security arrangements and consider carefully any travel around the country."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Colombia has suffered from internal armed conflict for over 50 years. In 2016, Colombia’s then-President Juan Manuel Santos signed a peace agreement with the Revolutionary Armed Forces of Colombia (FARC) movement to end the civil war."]},{"k":"p","s":["The peace agreement is still in place today, but Colombia remains seriously affected by conflict. Delays in the implementation of the peace agreement have led to a resurgence in violence in parts of the country. Much of this involves armed groups fighting for control of territory, the cocaine trade, and other illicit economies."]},{"k":"h","s":["Protests"]},{"k":"p","s":["Protests and demonstrations happen regularly throughout the country and often start at short notice. They can turn violent and may lead to an increase in the police and military presence. Road closures and roadblocks can cause travel disruptions for visitors."]},{"k":"p","s":["Avoid protests, strikes and demonstrations and follow the advice of local authorities or tour operators if you are affected. Allow extra time to reach your destination and monitor local media, including social media channels."]},{"k":"p","s":["There is a heightened risk of violence across the country when elections are held due to the interference of armed groups and criminal gangs in the electoral process. During national and state elections, avoid large gatherings or political rallies and be alert around polling stations."]},{"k":"h","s":["Crime"]},{"k":"p","s":["Drugs, organised crime and terrorism are inextricably linked in Colombia. There’s evidence of high levels of coca cultivation in:"]},{"k":"li","s":["Nariño Department"]},{"k":"li","s":["Cauca Department"]},{"k":"li","s":["Putumayo Department"]},{"k":"li","s":["Caquetá Department"]},{"k":"li","s":["Meta Department"]},{"k":"li","s":["Guaviare Department"]},{"k":"li","s":["the Catatumbo region in Norte de Santander Department"]},{"k":"li","s":["northern Antioquia Department"]},{"k":"li","s":["southern Bolivar Department"]},{"k":"p","s":["There’s a risk to your safety in any area where coca, marijuana or opium poppies are cultivated and near to cocaine processing labs."]},{"k":"p","s":["Illegal armed groups and criminal gangs are active in all of the departments where coca is cultivated, processed or transported, as well as in many cities. The risk is particularly significant in:"]},{"k":"li","s":["rural areas near to the borders with Panama, Venezuela and Ecuador"]},{"k":"li","s":["the Parque Nacional Natural de La Macarena in the Department of Meta"]},{"k":"li","s":["the port towns of Buenaventura in the Department of Valle de Cauca, Turbo in the Department of Antioquia and Tumaco in the Department of Nariño"]},{"k":"p","s":["Money laundering, extortion and prostitution rackets are all part of organised crime activity."]},{"k":"hs","s":["Street crime"]},{"k":"p","s":["Pickpocketing, mugging and armed robbery are a problem, especially in major cities, including Bogotá, Medellín, Cali and the Caribbean coast. British nationals have been robbed at gunpoint in the Candelaria area of Bogotá and across many cities in Colombia."]},{"k":"p","s":["Be vigilant in public places used by foreign nationals or near official buildings. Take care on city streets, especially in deprived areas of cities, after dark or if you are on your own. Do not carry large amounts of money or wear expensive-looking jewellery or watches."]},{"k":"hs","s":["Criminal kidnapping"]},{"k":"p","s":["Short-term opportunistic abductions known as ‘express kidnappings’ are common in Colombia. Criminals – often posing as taxi drivers may track and select a target victim, often from around ATMs and often at night. They also attack at random. The kidnappers force the victim to empty their bank account by making multiple transfers, or drive them to ATMs and force them to withdraw cash. Normally victims are quickly released, but there have been incidents where those who have resisted the kidnappers’ demands have been killed."]},{"k":"p","s":["Be aware of your surroundings and always let someone you trust know your whereabouts. Use ATMs during business hours so you can go inside a bank, supermarket or shopping centre."]},{"k":"p","s":["If you fall victim to a kidnapping, follow the kidnapper’s instructions."]},{"k":"p","s":["Kidnapping rates remain high and widespread in Colombia. Illegal armed groups kidnap hostages – both for ransom and for political purposes. While foreign nationals are not the primary targets, foreigners have been kidnapped in recent years, particularly those working for (or believed to be working for) oil, mining and related companies where armed groups operate."]},{"k":"p","s":["British nationals are seen as legitimate targets, including tourists, humanitarian aid workers, journalists and business travellers. If you are kidnapped, the reason for your presence is unlikely to protect you or secure your safe release."]},{"k":"hs","s":["Drug assisted robberies and sexual assaults"]},{"k":"p","s":["The British Embassy has received reports of criminals in Colombia using drugs to subdue their victims. This includes the use of scopolamine, which temporarily incapacitates victims. Criminals can administer drugs through food, drinks, cigarettes, aerosols and even paper flyers. Victims become disoriented quickly and are vulnerable to robbery, sexual assault, rape and other crimes."]},{"k":"p","s":["Criminals use dating applications and websites to identify and lure foreign nationals who are travelling alone and looking to meet local people. Criminals work in teams, with women easing the victim into a false sense of security. Victims are incapacitated and robbed. Incidents have been reported in nightclubs, bars, restaurants, public transportation, including taxis, and on city streets. Do not accept invitations from strangers to their accommodation, and do not invite strangers to your accommodation."]},{"k":"p","s":["Do not leave food or drinks unattended and do not take anything offered by strangers. These drugs can cause serious medical problems, including loss of consciousness, memory loss and can be fatal if administered in large quantities. Get local medical attention as soon as possible."]},{"k":"p","s":["Where possible, plan how you will travel to and from your destination. Only use pre-booked taxis."]},{"k":"hs","s":["Public offences"]},{"k":"p","s":["The law against the sexual abuse of children (aged 13 and under) is strictly enforced, especially when it involves tourists. If convicted, you could face a long prison sentence."]},{"k":"p","s":["The 141 national toll-free line and the ",["Child and Adolescent Police","https://www.policia.gov.co/proteccion-infancia"]," are available for 24-hour protection, emergencies and orientation of children and young people."]},{"k":"hs","s":["Police scams"]},{"k":"p","s":["Criminals posing as police are known to operate in Bogotá and elsewhere. They may ask to inspect money to see if it is counterfeit. If you are approached, ask them to escort you to the nearest local police station (CAI or ‘Centro de Atención Inmediata’)."]},{"k":"hs","s":["Crime in rural areas"]},{"k":"p","s":["In many rural areas, the authority of the Colombian state is limited, and the British Embassy’s ability to help British nationals in trouble in these areas will also be limited. Mobile and internet connection in rural areas is often limited."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Always carry a colour printout of the photo page and Colombian visa from your passport for identification. Keep the passport somewhere safe."]},{"k":"hs","s":["Alcohol"]},{"k":"p","s":["It is illegal to consume alcohol in public spaces."]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Colombia has severe penalties for possession, use or trafficking of illegal drugs."]},{"k":"p","s":["Colombian drug detection methods are sophisticated and anyone attempting to traffic drugs can expect to be arrested. British nationals have been arrested and detained for trying to smuggle cocaine out of the country. Prison conditions are harsh. Pack your own luggage and keep it with you at all times. Lock your cases to protect them from tampering. Never carry items for other people. Never exchange money for strangers, as this is a common practice among money launderers."]},{"k":"hs","s":["Spiritual cleansing"]},{"k":"p","s":["Traditional hallucinogenic tea, known as Yagé or Ayahuasca, is brewed and marketed to tourists as spiritual cleansing. The various preparations typically contain dimethyltryptamine (DMT), a strong hallucinogen that’s illegal in the UK and many other countries."]},{"k":"p","s":["There are many risks involved. Consumption is not regulated. Intoxicated travellers have been assaulted and robbed. There have also been reports of sexual assaults during these ceremonies."]},{"k":"p","s":["Health risks are not well understood and some people have suffered serious illnesses and in some cases death after taking these drugs. The jungle retreats are often a long way from medical facilities making the risks even greater. Some have basic medical services, but others do not. Some do not have an established plan for how you can access medical facilities in case of an emergency."]},{"k":"hs","s":["Taking photos in secure areas"]},{"k":"p","s":["Photographing military or strategic government sites is illegal."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex sexual activity is legal in Colombia, but same-sex relationships are not widely accepted, especially in rural areas."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Money"]},{"k":"p","s":["You can exchange US dollars and euros at banks and authorised money exchanges. Do not change money on the street."]},{"k":"p","s":["Credit and debit cards are widely accepted in hotels, shops and restaurants. Keep the receipts in case you need to show customs what money you have spent when you leave."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive a hire car or a UK vehicle, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in Colombia. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"],"."]},{"k":"p","s":["Hire car companies often have stricter requirements for their customers, such as:"]},{"k":"li","s":["a year of driving experience"]},{"k":"li","s":["being aged 18 years and over"]},{"k":"li","s":["holding an International Driving Permit (IDP)"]},{"k":"li","s":["a citizenship card or passport"]},{"k":"li","s":["a credit card to guarantee the vehicle hire"]},{"k":"p","s":["Carry all vehicle documents in physical form, in case you are pulled over by the police."]},{"k":"hs","s":["Driving standards"]},{"k":"p","s":["Driving standards are poor and traffic accidents are common. Avoid driving at night, which can be particularly hazardous. Do not hitch-hike. The risk of violence and kidnapping is higher in some rural areas, and there is a risk of being robbed at roadblocks set up by illegal armed groups. Main roads are generally safe during daylight hours."]},{"k":"hs","s":["Public transport"]},{"k":"p","s":["Be cautious when using public transport in Colombia."]},{"k":"p","s":["There have been several recent incidents of armed robbery on buses. Avoid displaying valuable items like laptops, cameras and mobile phones. Do not wear jewellery and only carry minimal amounts of cash. Avoid travelling on your own or at night, especially at border crossings or areas where there are few other people around. When travelling to remote areas, it may be safer to travel with others or take part in a tour with a reputable company."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["There have been reports of express kidnappings, assaults and robberies in unlicensed taxis. Use licensed telephone or internet-based taxi services whenever possible or book through your hotel. Many restaurants in Colombia will book a taxi for you. Do not hail taxis on the street."]},{"k":"p","s":["There are authorised taxi booths at most airports in Colombia. Bogotá’s El Dorado International Airport only allows authorised taxis to pick up passengers at its terminals. Authorised taxis are yellow with white licence plates and plate numbers on doors and roof. The driver’s information will be shown inside the vehicle. Well-known taxi companies can be booked via Uber and Cabify."]},{"k":"hs","s":["Landmines"]},{"k":"p","s":["There is a risk from landmines throughout Colombia, especially in rural and remote areas. Mined areas are often unmarked. Be vigilant when visiting remote areas or travelling off the main roads."]},{"k":"hs","s":["Air travel"]},{"k":"p","s":["The departmental capitals of Amazonas, Vaupes and Guainía are only accessible by air due to the lack of road infrastructure in these departments."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to prepare for and respond to ",["extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["2026-2027 El Niño"]},{"k":"p","s":["The Colombian Government has officially declared an El Niño phenomenon, with a high probability of a strong to very strong intensity until at least March 2027."]},{"k":"p","s":["El Niño is expected to generate unusually heavy rainfall, possible flooding and landslides, as well as higher temperatures, drought and wildfires. These may disrupt travel and other services."]},{"k":"p","s":["Extreme weather may affect your travel plans. Monitor local news and weather reports and follow the advice of local authorities. For official updates and forecasts, visit the ",["Colombian government website","https://www.ideam.gov.co/fenomeno-del-nino"]," (in Spanish)."]},{"k":"hs","s":["Hurricanes"]},{"k":"p","s":["Although uncommon, hurricanes and tropical storms can affect the Caribbean coast and the Archipelago of San Andres, Providencia and Santa Catalina."]},{"k":"p","s":["Monitor local news and check ",["World Meteorological Organization weather reports for Colombia","https://worldweather.wmo.int/en/country.html?countryCode=COL"],", the ",["US National Hurricane Center","https://www.nhc.noaa.gov/"],", and the Institute of Hydrology, Meteorology and Environmental Studies (IDEAM) (in Spanish)."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["There is a high risk of earthquakes across Colombia. Earthquakes occur regularly, particularly in Santander Department and the Andean Region."]},{"k":"p","s":["Familiarise yourself with safety procedures and any instructions in your hotel or accommodation."]},{"k":"p","s":["If an earthquake happens, monitor local media reports, follow instructions from the authorities and keep essential belongings, such as your passport and money, with you."]},{"k":"p","s":["Get real-time information (in Spanish) following an earthquake from:"]},{"k":"li","s":[["National Unit for Disaster Risk Management (UNGRD)","https://portal.gestiondelriesgo.gov.co/"]]},{"k":"li","s":[["Colombia’s Geological Services","https://www.sgc.gov.co/"]]},{"k":"p","s":["You can find a real-time earthquake map and further information about earthquakes in Colombia from ",["Colombia’s Geological Services","https://www.sgc.gov.co/sismos"],"."]},{"k":"p","s":["The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["There is a risk of floods and landslides after heavy rains throughout Colombia, especially in the Colombian Andes. Get local advice before travelling on mountain roads after heavy rain."]},{"k":"hs","s":["Volcanic eruptions"]},{"k":"p","s":["There are 25 active and monitored volcanoes in Colombia. Check the latest ",["daily bulletins about volcanic activity","https://www2.sgc.gov.co/Noticias/boletinesDocumentos/Forms/AllItems.aspx"]," (in Spanish)."]},{"k":"p","s":["If you are in areas of volcanic activity, monitor the ",["Servicio Geológico Colombiano","https://www.sgc.gov.co/volcanes"]," for any updates or alerts."]},{"k":"p","s":["Notify friends and family of your location, stay alert, and follow any advice from local security authorities or your travel operator. Be prepared to make travel arrangements or follow evacuation plans at short notice."]},{"k":"p","s":["Check before travelling on the Pan-American highway, which passes near a volcano. Call 767 for information (in Spanish) from the Colombian Highway Police about road closures."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Colombia. It only covers regions where the Foreign, Commonwealth & Development Office (FCDO) has specific advice."]},{"k":"p","s":["You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/colombia"]," and ",["safety and security advice","https://www.gov.uk/foreign-travel-advice/colombia/safety-and-security"],"."]},{"k":"h","s":["Colombia-Venezuela border and northern Colombia"]},{"k":"p","s":["FCDO advises against all but essential travel to:"]},{"k":"li","s":["the Catatumbo region of Norte de Santander Department"]},{"k":"li","s":["all of Arauca Department, except for the department capital, Arauca"]},{"k":"li","s":["the municipality of Puerto Carreño in Vichada Department, except for the department capital, Puerto Carreño"]},{"k":"li","s":["within 5km of the rest of the border with Venezuela, except for the city of Cúcuta"]},{"k":"p","s":["FCDO currently advises against all travel to ",["Venezuela’s border regions with Colombia","https://www.gov.uk/foreign-travel-advice/venezuela"],". You should not use any of the Colombia-Venezuela land crossings."]},{"k":"h","s":["Pacific coast and Colombia-Panama border"]},{"k":"p","s":["FCDO advises against all but essential travel to:"]},{"k":"li","s":["Chocó Department, except for the department capital Quibdó, the whale-watching towns of Nuquí and Bahía Solano and the tourist site of Capurganá"]},{"k":"li","s":["the western part of Valle del Cauca Department, including Buenaventura"]},{"k":"li","s":["the municipality of Jamundí, Valle del Cauca"]},{"k":"li","s":["the western part of Cauca Department"]},{"k":"li","s":["the South Pacific, Sanquianga and Telembi regions of Nariño Department"]},{"k":"li","s":["the southern part of Córdoba Department"]},{"k":"li","s":["the Urabá and Bajo Cauca regions of Antioquia Department"]},{"k":"li","s":["the southern part of Bolívar Department"]},{"k":"p","s":["The Pacific coast of Chocó is a popular eco-tourist destination. However, much of Chocó is remote. Illegal armed groups are active and involved in the drugs trade throughout the department and particularly near the border with Panama. If you intend to travel to the whale-watching towns of Bahia Solano and Nuqui, only do so by air and do not travel inland or along the coast out of town."]},{"k":"hs","s":["Darien Gap"]},{"k":"p","s":["The ‘Darien Gap’ is a dangerous area renowned for the presence of several illegal armed groups, illegal migration and drugs trafficking. There’s no road crossing between Colombia and Panama. Avoid crossing between Panama and Colombia by land."]},{"k":"h","s":["Colombia-Ecuador border and southern Colombia"]},{"k":"p","s":["FCDO advises against all but essential travel to within 5km of the border with Ecuador except for:"]},{"k":"li","s":["the border crossing on the Pan-American highway at the Puente Internacional de Rumichaca"]},{"k":"li","s":["the city of Ipiales in Nariño Department"]},{"k":"p","s":["FCDO advises against all but essential travel to Orito, San Miguel, Valle del Guamuez, Puerto Caicedo, Puerto Guzmán, Puerto Asis and Puerto Leguizamo in Putumayo Department."]},{"k":"h","s":["Central Colombia"]},{"k":"p","s":["FCDO advises against all but essential travel to:"]},{"k":"li","s":["all of Guaviare Department, except for the department capital San José de Guaviare"]},{"k":"li","s":["Cartagena del Chairá, San Vicente del Caguan, Puerto Rico, El Doncello, Paujil and La Montañita in Caquetá Department"]},{"k":"li","s":["the Ariari region of southern Meta, except for Caño Cristales"]},{"k":"p","s":["If travelling to the tourist site of Caño Cristales, travel by air from the town of La Macarena with a reputable tour company."]},{"k":"h","s":["Ciudad Perdida – ‘Lost City’"]},{"k":"p","s":["If you travel to the ‘Lost City’ in the Sierra Nevada de Santa Marta, only do so as part of an organised tour."]},{"k":"h","s":["San Agustín Archaeological Park"]},{"k":"p","s":["The San Agustín Archaeological Park (‘Parque Arqueológico de San Agustín’) is in the department of Huila. Enter and leave the park on the main road through Neiva or Popayán."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 123 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Colombia","https://travelhealthpro.org.uk/country/53/colombia#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Colombia","https://travelhealthpro.org.uk/country/53/colombia"],", including:"]},{"k":"li","s":["Yellow fever"]},{"k":"li","s":["Zika"]},{"k":"li","s":["Malaria"]},{"k":"li","s":["Dengue"]},{"k":"li","s":["Chikungunya"]},{"k":"p","s":["Altitude sickness is a risk in parts of Colombia, including Bogotá and areas in the Departments of Cundinamarca, Boyacá, Nariño and Antioquia. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"hs","s":["Drinking tap water"]},{"k":"p","s":["Tap water is safe to drink only in Bogotá. You should drink only bottled water and avoid ice in drinks."]},{"k":"h","s":["Medication and prescriptions"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["You can find most medication in pharmacies in large cities, but medicine for complex treatment may be unavailable in rural areas and small towns. You may need a prescription from a local doctor to get some controlled medicine."]},{"k":"p","s":["If you take prescription medication, you will be responsible for determining its legality in Colombia. Always keep your medication in the original container, bring sufficient quantities of your medication with you, pack your medication in your carry-on luggage and carry a copy of your prescriptions."]},{"k":"p","s":["Pharmacies in Colombia (‘droguerías’) have a cross on their signage and are easy to find in the main cities in Colombia. They are less common in rural areas. Most pharmacies in Colombia will have a delivery service. Prescriptions must be written in Spanish, in the metric system and using the medicine’s generic name."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Colombia"]},{"k":"p","s":["Medical facilities in Colombia vary widely in quality. In large cities and state capitals, private clinics provide good quality care for routine and complex treatment."]},{"k":"p","s":["Public health facilities and those in smaller cities are generally ill equipped and poorly funded. Ambulance services in remote areas are unreliable and public hospitals often lack adequate medical supplies."]},{"k":"p","s":["Make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment abroad and repatriation."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Colombia","https://www.gov.uk/government/publications/colombia-list-of-medical-facilities"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Colombia"]},{"k":"p","s":["Ambulance: 123"]},{"k":"p","s":["Fire: 119"]},{"k":"p","s":["Police: 123"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=colombia"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=colombia"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=colombia"]," in Colombia"]},{"k":"li","s":["dealing with a ",["death in Colombia","https://www.gov.uk/government/publications/colombia-bereavement-pack"]]},{"k":"li","s":["being ",["arrested or imprisoned in Colombia","https://www.gov.uk/government/publications/colombia-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"]," such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/colombia/british-embassy-bogota"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/colombia/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Colombia","https://www.gov.uk/government/publications/overseas-business-risk-colombia"]," on how to manage political, economic, and business security-related risks."]}],"chars":31732,"change":"New information about the the temporary deployment of security forces in the city of Cucuta (‘Warnings and Insurance’ page)."},"https://theconversation.com/what-scotland-is-getting-wrong-on-recycling-and-wales-is-getting-right-295633":{"r":"conversation","at":"2026-11-17T16:38Z","sha":"276a29163b43d58921b76cf232bf853c9fa9b0214df54fb2fe94298bd72d2d24","read":"https://theconversation.com/what-scotland-is-getting-wrong-on-recycling-and-wales-is-getting-right-295633","bytes":181141,"x":"fulltext v1","title":"What Scotland is getting wrong on recycling – and Wales is getting right","by":[{"n":"Ian Williams","r":"Professor of Applied Environmental Science, University of Southampton"}],"pub":"2026-11-16T10:11:20Z","mod":"","blocks":[{"k":"p","s":["Scotland has ambitions to become an environmental leader, but its recycling rate has just fallen to a five-year low."]},{"k":"p","s":["The Scottish household ",["recycling","https://theconversation.com/uk/search?q=recycling"]," rate fell from 44.3% in 2024 to 42.8% in 2025, according to ",["recently released figures","https://www.circularonline.co.uk/news/scottish-household-recycling-rate-falls-to-42-8-as-incineration-rises/"],". These ",["figures","https://www.bbc.co.uk/news/articles/c62ke84qwl1vo"]," also show the levels vary widely across the country, with Glasgow one of the lowest local authorities at only 24% and Clackmannanshire at 56%. The Scottish government had previously set a ",["recycling target","https://www.environment.gov.scot/our-environment/people-and-the-environment/waste-and-resources"]," of 70% of waste by 2025."]},{"k":"p","s":["It is tempting to blame Scottish households. But research has shown recycling is shaped by social, cultural and structural conditions. ",["Participation improves","https://doi.org/10.1016/j.resconrec.2005.09.005"]," when services fit people’s everyday lives and make recycling convenient. People need authorities to provide suitable local infrastructure, services and behavioural support to enable ",["effective recycling","https://doi.org/10.1016/j.wasman.2010.12.010"],"."]},{"k":"p","s":["Scotland’s recycling services remain ",["inconsistent and confusing","https://www.gov.scot/publications/household-recycling-code-practice-consultation-document/"],". This is partly down to the continuing variation between local authority systems. Depending on where someone lives, there can be differences in which materials are accepted, container types and colours and whether glass is collected at the kerbside."]},{"k":"p","s":["The wide variation between councils, from 18.2% to 56.5%, ",["points to inconsistent services","https://www.gov.scot/publications/household-recycling-code-practice-consultation-document/"]," rather than individual attitudes alone."]},{"k":"p","s":["Meanwhile, Scotland has struggled to introduce a ",["return scheme","https://www.gov.scot/publications/deposit-return-scheme-scotland-regulations-2020-amended-deposit-return-scheme-scotland-amendment-regulations-2025-deposit-return-scheme-scotland-designation-scheme-administrator-order-2025-full-bria/pages/7/"]," for drinks containers, where a deposit is paid and then returned when recycled. Initially expected to start in October 2025, this has been postponed to October 2027, and will no longer include glass, due to wrangles with ",["the UK government","https://consoc.org.uk/the-deposit-return-scheme/"]," over devolved powers."]},{"k":"p","s":["This was expected to raise recycling levels of eligible drinks containers to ",["around 90%","https://www.zerowastescotland.org.uk/resources/deposit-return-scheme-environmental-benefits"],". A similar ",["deposit scheme","https://re-turn.ie/2-5-billion-cans-and-bottles-re-turned/"]," in Ireland has been very successful at pushing up recycling levels."]},{"k":"h","s":["What Wales gets right"]},{"k":"p","s":[["UK-wide figures","https://www.gov.uk/government/statistics/uk-waste-data/uk-statistics-on-waste"]," also show a distinct difference between the four nations: Wales recycled 58.6% (up from 4.8% of household waste in ",["1998-99","https://www.gov.wales/new-stats-why-wales-outlier-uk-recycling-rates"],"), Northern Ireland 50.1%, England 43.8% and Scotland comes bottom at 42.7% in 2024. These outcomes reflect political choices, not simply how diligently households sort their rubbish. Scotland’s lower rate reflects ",["lack of access","https://www.gov.scot/publications/waste-reprocessing-infrastructure-scotland/"]," to convenient collection systems, cost barriers, limited reprocessing capacity and increasing incineration of recyclables."]},{"k":"p","s":["Overall, recycling has stalled across England, Scotland and Northern Ireland while ",["incineration of waste has expanded","https://static1.squarespace.com/static/5eabdfbe067c0b62fc7b58b7/t/6800cd36c2408b1f7ad8f645/1744883006223/uk-energy-from-waste-statistics-2024-4812.pdf"],"."]},{"k":"p","s":["The municipal rate of recycling has ",["increased to 68.4% in 2024-25","https://www.gov.wales/local-authority-municipal-waste-management-april-2024-march-2025-html"],". Municipal waste includes all local-authority-collected waste, including some commercial waste, street sweepings and litter bins."]},{"k":"p","s":["But ",["Wales shows","https://www.mdpi.com/2313-4321/7/4/46"]," that stagnation in recycling levels is not inevitable, and the nation has become a ",["global leader","https://www.gov.wales/new-stats-why-wales-outlier-uk-recycling-rates"]," on this front."]},{"k":"p","s":["This reflects a sustained Welsh government policy, ",["reinforced in 2021 with a new approach","https://www.gov.wales/beyond-recycling"]," that set statutory local authority targets, invested in collections, as well as monitoring and political backing. Wales also imposed a moratorium on new large-scale ",["energy-from-waste developments in 2021","https://www.mrw.co.uk/news/wales-introduces-immediate-moratorium-on-efw-24-03-2021/"],"."]},{"k":"p","s":["The Welsh system is not perfect. Its municipal rate remained below the 70% national target for 2024-25. Nevertheless, ",["20 of its 22 local authorities improved","https://www.gov.wales/local-authority-municipal-waste-management-april-2024-march-2025-html"],", demonstrating what sustained institutional pressure can achieve. Its experience suggests that targets work best when they are backed by infrastructure, accountability and stable long-term policy."]},{"k":"h","s":["Recycling history"]},{"k":"p","s":["The first UK recycling in the early 2000s focused on relatively accessible materials such as paper, glass, metals and ",["garden waste","https://doi.org/10.1016/S0921-3449(02)00106-4"],"."]},{"k":"p","s":["But further progress depends on addressing ",["food waste","https://doi.org/10.1016/j.wasman.2026.115536"],", ",["plastic films","https://www.mdpi.com/2073-4360/18/16/2031"],", ",["textiles","https://www.mdpi.com/2673-7248/5/4/41"],", ",["electrical products","https://doi.org/10.1016/j.wasman.2020.10.016"]," and ",["complex packaging","https://doi.org/10.3390/su17020556"],"."]},{"k":"p","s":["These streams are harder to collect, separate and process, while markets for some recovered materials, where waste is reused, remain uncertain. Variable quality, volatile prices and weak demand for some materials increase costs and risk, potentially ",["leaving councils without buyers","https://democracy.swansea.gov.uk/documents/s110653/9%20-%20Scrutiny%20-%20Recyclate%20Income%20Report%20Final.pdf?"],"."]},{"k":"p","s":["Another reason recycling have not climbed as high as predicted is that people cannot recycle materials that councils do not collect. To help people recycle more it is important to ",["eliminate confusing labels","https://product.sustainability-directory.com/question/why-are-some-plastic-recycling-labels-confusing/"],", redesign packaging that was ",["never designed to be recycled","https://www.asa.org.uk/news/disposing-of-misleading-ads.html"]," or create new markets for recovered materials."]},{"k":"h","s":["Burning not burying"]},{"k":"p","s":["It’s important to note that landfill reduction is also an important environmental achievement, and in Scotland, for instance, landfill use has declined – ",["down 82.5% since 2011","https://shiny.data.gov.scot/sepa/waste/household.html"]," – although incineration has increased. In 2024 1.86 million tonnes was incinerated, an increase of 239,000 tonnes (14.7%) from 2023. Poorly managed landfill sites can pollute soil and water, release methane and require monitoring long after closure. The ",["1999 EU Landfill Directive","https://eur-lex.europa.eu/eli/dir/1999/31/oj/eng"],", landfill tax, statutory targets and kerbside collections helped transform the system."]},{"k":"p","s":["But the UK is increasingly burning what it no longer wants to bury. In 2024, 63 energy-from-waste plants burned ",["16.8 million tonnes of residual waste","https://static1.squarespace.com/static/5eabdfbe067c0b62fc7b58b7/t/6800cd36c2408b1f7ad8f645/1744883006223/uk-energy-from-waste-statistics-2024-4812.pdf"],". Since 2024, there are ",["ten incinerators under construction in England and two in Scotland","https://ukwin.org.uk/facts/"],", but none in Wales and Northern Ireland. As people recycle more there’s less need for these, so why are so many being built?"]},{"k":"p","s":["For non-recyclable waste, modern incineration may be preferable to landfill. It reduces waste volume and can ",["generate electricity","https://www.planete-energies.com/en/media/article/incineration-heating-power-refuse"]," or heat. But it is controversial. ",["Incineration is the dirtiest way","https://www.bbc.co.uk/news/articles/cp3wxgje5pwo"]," the UK generates power. It ",["emits carbon and causes smells","https://www.bbc.co.uk/news/articles/c1eypqxd928o"]," as well as destroying materials that could otherwise remain in use. It also often causes nearby residents to ",["worry about health risks","https://www.bbc.co.uk/news/articles/cj45vk7rj0lo"],"."]},{"k":"p","s":["In 2024, 82.3% of Scottish household waste classified as “other diversion from landfill” was managed through incineration. ",["Landfilled household waste fell by 37.7%","https://shiny.data.gov.scot/sepa/waste/household.html"],", but the quantity managed through ",["“other diversion” rose by 16.1%","https://shiny.data.gov.scot/sepa/waste/household.html"],". Scotland is therefore managing its residual waste differently, but without achieving an equivalent improvement in waste prevention or recovering or reusing materials."]},{"k":"h","s":["The next waste revolution"]},{"k":"p","s":["The UK’s reduction in how much waste it deposits into landfill was the first waste revolution. The next change must be preventing waste and keeping products and materials in use for longer."]},{"k":"p","s":["Governments should ensure residual waste contracts do not penalise councils for reducing rubbish. They should reward durable, repairable and genuinely recyclable products. Priority should be given to food, flexible plastics, textiles, electrical equipment and complex packaging."]},{"k":"p","s":["Wales shows that sustained recycling progress is also possible. The next waste revolution will begin when conserving materials takes priority over finding another way to destroy them. Those in Scotland who want the country to take an environmental leadership role should take note."]}],"chars":6733},"https://www.gov.uk/foreign-travel-advice/chad":{"r":"govuk","at":"2026-11-17T17:18Z","sha":"e13cd185b957b5a1a53c63f99fcc50146f12f1241487ae8794f667c0ac48e88c","read":"https://www.gov.uk/api/content/foreign-travel-advice/chad","bytes":65183,"x":"fulltext v1","title":"Chad travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-01-30T00:00:00+00:00","mod":"2026-11-04T14:33:29+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"hs","s":["Borkou, Ennedi Ouest, Ennedi Est and Tibesti provinces"]},{"k":"p","s":["FCDO advises against all travel to the northern provinces of Chad:"]},{"k":"li","s":["Borkou Province"]},{"k":"li","s":["Ennedi Ouest Province"]},{"k":"li","s":["Ennedi Est Province"]},{"k":"li","s":["Tibesti Province"]},{"k":"hs","s":["Kanem Province, including Nokou"]},{"k":"p","s":["FCDO advises against all travel to the western part of Kanem Province, including the town of Nokou."]},{"k":"hs","s":["Lake Chad region"]},{"k":"p","s":["FCDO advises against all travel to the Lake Chad region."]},{"k":"hs","s":["Within 30km of all Chad’s other borders"]},{"k":"p","s":["FCDO advises against all travel to within 30km of all of Chad’s other borders."]},{"k":"hs","s":["The rest of Chad"]},{"k":"p","s":["FCDO advises against all but essential travel to the rest of Chad, including the capital, N’Djamena."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/chad/regional-risks"],"."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"h","s":["Limited UK government support"]},{"k":"p","s":["Support for British nationals is severely limited in Chad with assistance provided remotely from British High Commission Yaoundé. In-person assistance is not available including from the British Embassy in N’Djamena."]},{"k":"p","s":["If there is serious violence, unrest or a deterioration in the security situation, it could be difficult to leave safely."]},{"k":"p","s":["Do not rely on the UK government to evacuate you as they may not be able to do so. Have your own plans on how you would leave the country, make sure you keep all travel documentation up to date and monitor the local situation."]},{"k":"h","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/chad/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Chad’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Chad set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the Chadian Embassy in Belgium or the Chadian Embassy in France."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Chad, your passport must have an ‘expiry date’ at least 6 months after the date you arrive."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to visit Chad."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["Since May 2026, visa applications for Chad can be submitted online through the ",["official e-Visa platform","https://evisa.td/"],". Applicants can complete the application, upload supporting documents, pay the visa fee, and track the status of their application online. The Chadian authorities recommend applying at least seven days before travel."]},{"k":"p","s":["Alternatively, you can contact a Chadian Embassy for assistance with visa applications. To apply for a visa contact the Chadian Embassy in Belgium, or the ",["Chadian Embassy in France","https://ambatchadparis.fr/"],"."]},{"k":"h","s":["Registering with the police"]},{"k":"p","s":["If you stay in Chad more than 72 hours, you must register with the police. The immigration officer will tell you to go to the Commissariat Central (police headquarters) on Avenue General Kerim Nassour (formerly Boulevard de Strasbourg). You must bring a passport photograph."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To enter Chad, you must have a certificate to prove you’ve had a yellow fever vaccination if you’re coming from a ",["country listed as a transmission risk","https://nathnacyfzone.org.uk/factsheet/65/countries-with-risk-of-yellow-fever-transmission"],"."]},{"k":"p","s":["For full details about medical entry requirements and recommended vaccinations, including yellow fever, see ",["TravelHealthPro’s Chad guide","https://travelhealthpro.org.uk/country/47/chad#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of Chad. You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"h","s":["Safety and security"]},{"k":"p","s":["This guide also has safety advice for ",["regions of Chad","https://www.gov.uk/foreign-travel-advice/chad/regional-risks"],"."]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Chad"]},{"k":"p","s":["Terrorists are very likely to try to carry out attacks in Chad."]},{"k":"p","s":["Terrorist attacks could be indiscriminate and occur without warning, including in places visited by foreign nationals, such as:"]},{"k":"li","s":["hotels, restaurants, bars and nightclubs"]},{"k":"li","s":["shopping areas and markets"]},{"k":"li","s":["airports and other transport hubs"]},{"k":"li","s":["places of worship (especially churches)"]},{"k":"li","s":["national parks"]},{"k":"li","s":["foreign embassies and other diplomatic or military facilities"]},{"k":"li","s":["national and local government facilities"]},{"k":"p","s":["Stay vigilant and aware of your surroundings at all times. Keep up to date with local media reports and follow the advice of local authorities. Avoid:"]},{"k":"li","s":["public marches and demonstrations"]},{"k":"p","s":["Be extra cautious during elections, festivities, and religious and public holidays, or at times of heightened political tensions."]},{"k":"p","s":["The terrorist groups Islamic State West Africa and Boko Haram remain active in the Lake Chad region and continue to carry out attacks against military positions and civilians. In May 2026, Boko Haram attacked a military position on Barka Tolorom Island in Lake Chad, killing and injuring Chadian soldiers. Chadian security forces continue to conduct counter-terrorism operations in the Lac Province region."]},{"k":"hs","s":["Terrorist kidnapping"]},{"k":"p","s":["There is a high risk of terrorist kidnapping in the Lake Chad Basin and the border areas with Cameroon, Nigeria and Niger."]},{"k":"p","s":["British nationals are seen as legitimate targets, including tourists, humanitarian aid workers, journalists and business travellers. If you are kidnapped, the reason for your presence is unlikely to protect you or secure your safe release."]},{"k":"p","s":["Over the last 10 years, terrorist groups in the Sahel have kidnapped western nationals across the region, including tourists, non-governmental organisation (NGO) workers and diplomats, and are still holding several hostages. Kidnappers have killed some hostages, including several British nationals."]},{"k":"p","s":["Terrorist groups active in the Lake Chad Basin and the Sahel region include Jamaat Nusrat al-Islam wal Muslimeen (JNIM), Islamic State West Africa (ISWA), Islamic State Greater Sahara (ISGS), Al-Qaida in the Islamic Maghreb (AQIM), Al Murabitoun, Ansar Dine and Boko Haram. These groups can carry out attacks and kidnappings over long distances. Boko Haram and ISWA also take hostages from neighbouring Cameroon, northern Nigeria and the Diffa region of Niger. Kidnapping for ransom is the main source of finance for JNIM. Criminal gangs also carry out kidnappings for terrorist groups in return for financial rewards."]},{"k":"p","s":["You should always stay alert, especially when travelling and in crowded public places, including camps for displaced people, religious gatherings and insecure spaces such as places of worship, markets, shopping areas, hotels, bars, nightclubs, restaurants and transport hubs. Make sure you have carefully considered the threat and have reasonable, proportionate mitigation measures in place."]},{"k":"p","s":["The long-standing policy of the British government is not to make substantive concessions to hostage takers. The British government considers that paying ransoms and releasing prisoners builds the capability of terrorist groups and finances their activities. This can, in turn, increase the risk of further hostage-taking. The Terrorism Act (2000) makes payments to terrorists illegal."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["There is a continuing risk of instability in Chad, particularly in its border regions and during major political events."]},{"k":"p","s":["In February 2024, several people were killed or injured in armed clashes between supporters of the PSF (Socialist Party without Borders) and government forces in Chad’s capital. The leader of the PSF, Yaya Dillo, was amongst those killed."]},{"k":"p","s":["Public demonstrations, including anti-government protests, have not been common in Chad since October 2022, when security forces fired live ammunition during demonstrations and civilians were killed and injured."]},{"k":"p","s":["Demonstrations have in the past targeted foreign, national and local government facilities, resulting in damage. Monitor the local news to help you avoid such gatherings. If a crowd gathers near you, leave the area immediately."]},{"k":"p","s":["While celebratory gunfire is illegal in Chad, it can occur during celebrations, including during weddings and some political events. Celebratory gunfire led to civilian deaths and injuries in May 2024 after the announcement of provisional election results. In the event of celebratory gunfire, take cover on the lower levels of buildings and away from windows."]},{"k":"p","s":["In 2021, an armed convoy belonging to the rebel group Le Front pour l’Alternance et la Concorde au Tchad (FACT) crossed into Chad from Libya and fought government forces. President Idriss Deby Itno was killed. The UK government advised British nationals to leave Chad. The British Embassy in N’Djamena closed temporarily."]},{"k":"p","s":["In January 2025, a fatal shooting took place near the Presidential Palace in N’Djamena. Remain vigilant, stay away from the area at night, and use alternative routes where possible."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Carjacking"]},{"k":"p","s":["There is a high risk of carjacking on roads outside N’Djamena, including during the daytime."]},{"k":"hs","s":["Robbery"]},{"k":"p","s":["Robbery is common in some residential areas of N’Djamena. Robbers sometimes target foreign nationals because they’re considered wealthier."]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["Stay alert and be particularly cautious about street crime. Do not carry large sums of money, jewellery or other valuables. Avoid isolated or less developed areas of towns and do not go out alone or at night."]},{"k":"p","s":["To reduce your personal risk, do not walk after dark. Walking during daylight hours should be kept to a minimum and only undertaken in well-frequented areas for short distances, and should be kept to an absolute minimum. Driving remains preferable to walking, and consider using pre-arranged secure transport to get around N’Djamena. Keep car doors locked and windows closed."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"p","s":["Respect local traditions, customs, laws and religions. Make sure you do not offend local cultures or religious beliefs, especially during the holy month of Ramadan or if you plan to visit religious areas."]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Always carry a certified copy of your passport. If you cannot show ID, the police could detain you. You could also face delays if you have to leave the country. If you live in Chad, always carry your residence permit."]},{"k":"hs","s":["Ramadan"]},{"k":"p","s":["Ramadan is a holy month for Muslims. The dates vary by year and country. During Ramadan, avoid eating, drinking, smoking, chewing gum, playing loud music, or swearing in public. You should also:"]},{"k":"li","s":["check opening hours of shops and restaurants"]},{"k":"li","s":["respect local customs and dress conservatively"]},{"k":"li","s":["be aware that fasting can cause tiredness and affect driving standards, particularly near sunset"]},{"k":"li","s":["be patient and show tolerance"]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Penalties for drug use and possession are severe and usually include a prison sentence. Conditions in local prisons are harsh."]},{"k":"hs","s":["Using cameras"]},{"k":"p","s":["It is illegal to photograph military sites, government buildings or airports without a permit."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex sexual activity is illegal in Chad, with penalties of imprisonment ranging from 3 months to 2 years and a fine of between 50,000 and 500,000 CFA francs. Same-sex relationships are not widely accepted by Chadian society."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Chad, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You must convert your UK driving licence to a Chadian one to drive in Chad."]},{"k":"hs","s":["Driving standards and security"]},{"k":"p","s":["Road travel can be dangerous due to road conditions and the standard of driving. Accidents involving motorbikes are common. Crowds quickly gather around the scene of an accident and, while rarely violent, can be intimidating. If you’re involved in an accident, try to contact the police or other local authority immediately. Phone: 2020 or 117 (police) or 112 or 18 (fire and ambulance)."]},{"k":"p","s":["Outside of N’Djamena, do not travel by road after dark due to the risk of crime and poor road conditions. Military guards may think you’re a security risk if you drive near government buildings at night."]},{"k":"p","s":["Travel in convoy, keep doors locked and carry spare fuel and supplies. Fuel shortages can occur across Chad and availability may be unreliable. There may be particular disruptions to domestic fuel production in October and November 2026 as a result of the closure of the Djermaya refinery, including an increased risk of shortages, long queues at filling stations and travel delays. Especially if travelling outside of N’Djamena, ensure you have sufficient fuel, supplies, and contingency plans before departure."]},{"k":"p","s":["Police checkpoints are common. Officers may ask you to show your passport, driving licence and vehicle registration documents."]},{"k":"p","s":["Take great care on the road in front of the Presidential Palace in N’Djamena where there have been past shootings including fatalities."]},{"k":"hs","s":["Travelling outside N’Djamena"]},{"k":"p","s":["To travel outside N’Djamena, you must get authorisation from the ",["Ministry of the Interior","https://interieur.gouv.td/"],". Many businesses arrange escorts when their western staff travel outside the capital for any reason. Some humanitarian organisations may need to apply for further authorisations to travel to the east of Chad."]},{"k":"p","s":["Before you consider any travel outside the capital, take professional security advice. You should:"]},{"k":"li","s":["follow your employer’s security advice, if available"]},{"k":"li","s":["inform the correct Chadian authorities of your journey"]},{"k":"li","s":["use a police or military escort and carry communications equipment"]},{"k":"li","s":["have the right permits"]},{"k":"li","s":["hold appropriate travel insurance"]},{"k":"li","s":["be aware of medical services/ limitations along your route"]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to prepare for and respond to ",["extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Rainy season"]},{"k":"p","s":["Roads are poor and often impassable during the rainy season from July to October, especially in the south. Heavy rains can cause major flooding in many areas, particularly in the south and east. Bring food and clean water with you."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Chad. It only covers regions where FCDO has specific advice."]},{"k":"p","s":["You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/chad"]," and ",["safety and security advice","https://www.gov.uk/foreign-travel-advice/chad/safety-and-security"],"."]},{"k":"h","s":["Borkou, Ennedi Ouest, Ennedi Est and Tibesti provinces"]},{"k":"p","s":["FCDO advises against all travel to the northern provinces of Chad:"]},{"k":"li","s":["Borkou Province"]},{"k":"li","s":["Ennedi Ouest Province"]},{"k":"li","s":["Ennedi Est Province"]},{"k":"li","s":["Tibesti Province"]},{"k":"p","s":["There are many landmines near the Chad-Libya border in these provinces. The northern provinces are also unsafe due to the presence of rebel groups and contested gold mines."]},{"k":"h","s":["Kanem Province, including Nokou"]},{"k":"p","s":["FCDO advises against all travel to the western part of Kanem Province, including the town of Nokou due to the risk of terrorism. See ",["Terrorism in Chad","https://www.gov.uk/foreign-travel-advice/chad/safety-and-security"],"."]},{"k":"h","s":["Lake Chad region"]},{"k":"p","s":["FCDO advises against all travel to the Lake Chad region. There is a high risk of terrorist kidnapping in the Lake Chad region. See ",["Terrorism in Chad","https://www.gov.uk/foreign-travel-advice/chad/safety-and-security"],"."]},{"k":"h","s":["Within 30km of all Chad’s other borders"]},{"k":"p","s":["FCDO advises against all travel to within 30km of all of Chad’s other borders."]},{"k":"p","s":["The Chad-Sudan border is closed to travellers, with limited humanitarian exceptions. Since late 2025, there has been increased insecurity along the eastern border, as a result of the conflict in neighbouring Darfur, Sudan, including armed and fatal clashes on the Chad side of the border and reports of aerial attacks near towns such as Tiné."]},{"k":"p","s":["The Central African Republic (CAR) is unstable and the border area is highly insecure, with limited government presence and active armed groups. In October 2026, Chad accused the CAR military of conducting an attack against suspected rebels that infringed Chadian territory in Tissi, at the intersection between the CAR, Chad and Sudan borders, with a number of people injured as a result."]},{"k":"h","s":["The rest of Chad"]},{"k":"p","s":["FCDO advises against all but essential travel to the rest of Chad, including the capital, N’Djamena."]},{"k":"h","s":["The Sahel region"]},{"k":"p","s":["There is a high risk of terrorist kidnapping in the Sahel region, which includes Chad, Mauritania, Mali, Burkina Faso and Niger. See ",["Terrorism in Chad","https://www.gov.uk/foreign-travel-advice/chad/safety-and-security"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 112 or 18 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Chad","https://travelhealthpro.org.uk/country/47/chad#Vaccine_Recommendations"]]},{"k":"li","s":["see how to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Chad","https://travelhealthpro.org.uk/country/47/chad"],", including:"]},{"k":"li","s":["malaria"]},{"k":"li","s":["cholera"]},{"k":"li","s":["dengue"]},{"k":"p","s":["Altitude sickness is a risk in parts of Chad. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"p","s":["You should drink or use only boiled or bottled water and avoid ice in drinks."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Chad"]},{"k":"p","s":["Medical facilities in Chad are poor. Even in N’Djamena hospitals are stretched and sometimes affected by strikes. Make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment abroad and repatriation."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Chad","https://www.gov.uk/government/publications/chad-list-of-medical-facilities"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Chad"]},{"k":"p","s":["Ambulance and fire: 112 or 18"]},{"k":"p","s":["Police: 2020 or 117"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Chad"]," in Chad"]},{"k":"li","s":["being ",["arrested or imprisoned in Chad","https://www.gov.uk/government/publications/chad-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/chad/british-embassy-ndjamena"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/chad/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":20233,"change":"This travel advice has been reviewed for accuracy with changes made throughout, including updated information about applying for a visa, terrorism in Chad, terrorist kidnapping, political situation, robbery, protecting yourself and your belongings, Ramadan, driving standards and security, travelling"},"https://www.gov.uk/foreign-travel-advice/turkey":{"r":"govuk","at":"2026-11-20T17:20Z","sha":"7ef5a660b9b9da742a3488797aca36f41cd956514e260b61189f94009e334ec5","read":"https://www.gov.uk/api/content/foreign-travel-advice/turkey","bytes":114094,"x":"fulltext v1","title":"Turkey travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-03-20T00:00:00+00:00","mod":"2026-11-18T16:36:28+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"hs","s":["Turkey-Syria border"]},{"k":"p","s":["FCDO advises against all travel to within 10km of the border with Syria due to fighting and a heightened risk of terrorism. If you are in Syria, follow ",["FCDO Travel Advice for Syria","https://www.gov.uk/foreign-travel-advice/syria"],". The FCDO cannot facilitate entry for British nationals into Turkey from Syria."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/turkey/regional-risks"],"."]},{"k":"h","s":["Support from the UK government"]},{"k":"p","s":["While 24-hour consular assistance is available by phone or online, in-person consular support is severely limited in areas where we advise against travel."]},{"k":"h","s":["Regional tensions"]},{"k":"p","s":["The context in the Middle East remains deeply unpredictable and the risk of sudden escalation is high. Since conflict began in early 2026, Iran has stated its intention to target locations associated with the US and Israel, including, but not limited to, organisations, businesses, facilities, and institutions. There have been strikes and retaliatory attacks by Iran and others across the region against civilian and military infrastructure. There remains a risk of further attacks across the region at short notice."]},{"k":"p","s":["British nationals in, or planning to travel through, the Middle East should be prepared for possible flight cancellations, airspace closures, and travel disruptions. You should:"]},{"k":"li","s":["read ",["If you’re affected by a crisis abroad - GOV.UK","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],". This includes guidance on “how to prepare for a crisis” with suggestions on what you might include in your emergency supplies and “what to do in a crisis”"]},{"k":"li","s":["sign up to ",["FCDO Travel Advice email alerts","https://www.gov.uk/foreign-travel-advice/turkey/email-signup"]]},{"k":"li","s":["follow advice from the local authorities"]},{"k":"li","s":["monitor local and international media for the latest information, including updates relating to airports and airspace which could close at short notice"]},{"k":"li","s":["stay away from areas around security or military facilities"]},{"k":"li","s":["keep your departure plans under review, and ensure your travel documents are up to date"]},{"k":"li","s":["if advised to take shelter, stay indoors or find the nearest safe building or designated shelter. An interior stairwell or a room with as few external walls or windows as possible may provide additional protection. The greatest risk is from falling debris caused by intercepts, and you are safest inside a secure structure. Do not approach or touch any drone or missile fragments or unusual objects"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide and any specific travel advice that applies to you:"]},{"k":"li","s":[["women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":[["disabled travellers","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":[["LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":[["solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":[["volunteering and adventure travel","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help British nationals make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/turkey/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of the current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Turkey set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Turkish Embassy in the UK","https://london-emb.mfa.gov.tr/Mission"],"."]},{"k":"h","s":["Entering Turkey across the land border from Iran"]},{"k":"p","s":["The border remains open visa-free for people travelling on UK or Iranian passports (for stays of up to 90 days). If you are a British national intending to cross the land border from Iran into Turkey, you must request facilitation from the British Embassy in Ankara ",["by contacting the FCDO","https://www.contact.service.csd.fcdo.gov.uk/home"]," before travelling to the border. You must state which border point you intend to use and provide personal details (name, date of birth, details of travel document used to enter Turkey). Also indicate whether you are contacting from Iran or from the UK on behalf of a relative."]},{"k":"p","s":["The Turkish authorities advise that the Iranians have closed the crossing point at Esendere-Serow on the Iranian side to daily traders entering and exiting over the course of a day."]},{"k":"p","s":["The usual ",["entry requirements","https://www.gov.uk/foreign-travel-advice/turkey/entry-requirements"]," will apply, including that British nationals can enter without a visa for up to 90 days in any 180-day period."]},{"k":"p","s":["If you intend to leave Iran overland, you do so at your own risk. In Iran, holding a British passport or having perceived connections to the UK can be reason enough for the Iranian authorities to detain you."]},{"k":"p","s":["Read more FCDO advice ",["If you’re affected by a crisis abroad - GOV.UK","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Turkey, your passport must have an ‘expiry date’ at least 150 days after the date you arrive and at least 1 blank page."]},{"k":"p","s":["If you live in Turkey, your passport must be valid for 6 months from the date you arrive."]},{"k":"p","s":["If entering at a land border, make sure officials stamp and date your passport at the border crossing."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can visit Turkey without a visa for up to 90 days in any 180-day period, for business or tourism."]},{"k":"p","s":["If you hold a British citizen passport, you can visit Turkey without a visa for up to 90 days in any 180-day period, for business or tourism"]},{"k":"p","s":["If you hold ",["another type of British passport","https://www.gov.uk/types-of-british-nationality"],", you will need a visa and should check visa requirements with the Turkish Embassy or Consulate General before you travel."]},{"k":"p","s":["To enter Turkey for education, employment or medical purposes, or in other special cases, check the ",["information on applying for a visa","https://www.mfa.gov.tr/general-information-about-turkish-visas.en.mfa"],". If you plan to work in Turkey, make sure you have the correct permits."]},{"k":"h","s":["Day trips to Greek islands"]},{"k":"p","s":["If you are considering a day trip to a Greek Island, be aware that Greece is in the Schengen Zone and has introduced the European Union (EU) ",["Entry Exit System (EES)","https://www.gov.uk/guidance/eu-entryexit-system"],"."]},{"k":"p","s":["This applies to any non-EU national travelling from Turkey into the EU by land, sea or air (excluding airport transit). EES may take each passenger a few extra minutes to complete, so be prepared to wait longer than usual at the border."]},{"k":"p","s":["Read ",["Greece’s travel advice","https://www.gov.uk/foreign-travel-advice/greece/entry-requirements"]," for further details."]},{"k":"h","s":["Travelling with children"]},{"k":"p","s":["If leaving Turkey with a dual British-Turkish national child who is 18 or younger, you may need to show permission to travel from the Turkish parent."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Turkey guide","https://travelhealthpro.org.uk/country/227/turkey#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Turkey","https://www.trade.gov.tr/customs-formalities/frequently-asked-questions/passenger-transactions"],". You must declare anything that may be prohibited or subject to any tax or duty."]},{"k":"p","s":["Some goods are prohibited – you cannot take them into or out of Turkey. These include:"]},{"k":"li","s":["controlled drugs"]},{"k":"li","s":["firearms"]},{"k":"li","s":["offensive weapons, for example flick knives and self-defence sprays"]},{"k":"li","s":["endangered animal and plant species"]},{"k":"li","s":["indecent and obscene material"]},{"k":"hs","s":["Taking money into and out of Turkey"]},{"k":"p","s":["There is no limit on the amount of foreign currency or Turkish lira you can take into Turkey."]},{"k":"p","s":["You must not take Turkish lira worth more than 5000 US dollars out of the country."]},{"k":"p","s":["If you have other currency worth more than 5000 US dollars to take out of Turkey, you must declare it to Turkish Customs."]},{"k":"p","s":["You may need to ",["demonstrate where the currency came from","https://www.ktb.gov.tr/EN-120418/foreign-exchange.html"],"."]},{"k":"h","s":["Safety and security"]},{"k":"p","s":["This guide also has safety ",["advice for regions of Turkey","https://www.gov.uk/foreign-travel-advice/turkey/regional-risks"],"."]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Turkey"]},{"k":"p","s":["Terrorists are likely to try to carry out attacks in Turkey."]},{"k":"p","s":["Most terrorist attacks have occurred in southeast Turkey, Ankara and Istanbul. You should remain aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"p","s":["See ",["Regional risks","https://www.gov.uk/foreign-travel-advice/turkey/regional-risks"]," for details about the areas in south-east Turkey where FCDO advises against travel."]},{"k":"p","s":["There have been several attacks involving knives, firearms and explosives. Attacks could be indiscriminate including in places visited by foreign nationals, such as:"]},{"k":"li","s":["public buildings"]},{"k":"li","s":["places of worship"]},{"k":"li","s":["airports"]},{"k":"li","s":["large public gatherings, including major events, public holidays, religious occasions"]},{"k":"p","s":["Examples of recent attacks include:"]},{"k":"li","s":["in April 2026, two police officers were injured after three gunmen opened fire near a building housing the Israeli Consulate in Istanbul"]},{"k":"li","s":["in September 2025, three police officers were killed and three people injured in an attack on a police station by a lone gunman in Izmir"]},{"k":"li","s":["in October 2024, five people were killed and 22 injured in an attack on the Turkish Aerospace Industries’ facility in Kahramankazan, 40km northwest of central Ankara"]},{"k":"li","s":["in February 2024, one person was killed in an armed attack on the Çağlayan courthouse in Istanbul by the terrorist group DHKP/C"]},{"k":"li","s":["in January 2024, one person was killed by two gunmen in the Santa Maria Catholic Church in Sariyer, in an attack claimed by Daesh"]},{"k":"li","s":["in 2022, six people were killed in an explosion in central Istanbul"]},{"k":"p","s":["Extremist groups based in Syria, including Daesh and Al-Qaeda linked groups, have the capacity to carry out attacks in Turkey. Daesh has previously targeted border crossings and nearby locations on the Syrian side of the border."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Regular demonstrations and protests are currently taking place in Istanbul and other cities across Turkey. Demonstrations may become violent. The police response has included use of tear gas and water cannons."]},{"k":"p","s":["Events in Israel and Palestine have led to heightened tensions in the region and in locations across Turkey. Demonstrations continue to occur outside diplomatic missions connected to the conflict in major cities, particularly Israeli diplomatic missions in Ankara and Istanbul."]},{"k":"p","s":["Avoid all demonstrations and leave the area if one develops. Local transport routes may be disrupted."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["Street robbery and pickpocketing are common in the major tourist areas of Istanbul. Be aware of your personal belongings and make sure they are always secure."]},{"k":"hs","s":["Counterfeit banknotes"]},{"k":"p","s":["Banks and money exchanges may not accept 50 or 100 US dollar bills, due to a reported surge in counterfeit banknotes of these denominations in Turkey. You should not accept these banknotes where possible."]},{"k":"hs","s":["Drink and food spiking"]},{"k":"p","s":["Be wary of strangers approaching you to change money, or to take you to a restaurant or nightclub. If strangers offer you food and drink these could be spiked. Buy your own drinks and always keep sight of them."]},{"k":"hs","s":["Methanol poisoning"]},{"k":"p","s":["There has been an increase in cases of serious illness caused by alcoholic drinks containing methanol in popular travel destinations around the world."]},{"k":"p","s":["In Turkey, including Ankara and Istanbul, people have died or suffered serious illness after drinking illegally produced local spirits and counterfeit bottles of branded alcohol."]},{"k":"p","s":["Even small amounts of methanol can kill. It is not possible to identify methanol in alcoholic drinks by taste or smell. See ",["Travel Aware Drink Spiking and methanol poisoning","https://travelaware.campaign.gov.uk/spiking-and-methanol-poisoning/"]," for information about how to reduce the risks."]},{"k":"p","s":["Seek urgent medical attention if you or someone you are travelling with show the ",["signs of methanol poisoning","https://travelaware.campaign.gov.uk/spiking-and-methanol-poisoning/"]," after drinking."]},{"k":"hs","s":["Sexual assault"]},{"k":"p","s":["Among the 4.27 million British travellers that visited Turkey in 2025, 29 cases of sexual assault, including rape, were reported to British consular staff. The majority of cases that have been reported took place during the tourist season in coastal resort areas. Often these crimes were committed by someone the victim may have met during the day, with a significant number being by hotel or spa staff. There have also been sexual attacks on minors visiting toilet facilities alone. Be extra vigilant in these situations."]},{"k":"p","s":["Take extra precautions:"]},{"k":"li","s":["make sure children and young people are always accompanied by known and trusted people and not left alone with hotel or excursion staff"]},{"k":"li","s":["use reputable providers for any services and excursions, carry out research beforehand, including by consulting your tour operator if you have one"]},{"k":"li","s":["don’t unnecessarily share personal details such as, information about your accommodation, personal contact information or social media accounts"]},{"k":"p","s":["See ",["advice for women travelling abroad","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]," and ",["information for British nationals affected by rape or sexual assault abroad","https://www.gov.uk/guidance/victim-of-rape-and-sexual-assault-abroad"]]},{"k":"p","s":["If you experience sexual harassment or assault, or if you feel threatened or unsafe, report it as soon as possible to the hotel and to the Turkish police or gendarmerie. Call 112 for police. Contact your nearest British Consulate for Consular support."]},{"k":"hs","s":["Taxi safety"]},{"k":"p","s":["Accepting lifts from drivers of unofficial taxis is highly risky. Find a registered taxi, note the registration number before entering and ensure the fare is metered. App-based taxis and pre-booked taxis are also widely available."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["E-sims"]},{"k":"p","s":["Access to some e-sim services is restricted in Turkey. Check with your provider before travelling."]},{"k":"hs","s":["Ramadan"]},{"k":"p","s":["Ramadan is a holy month for Muslims in Turkey. The next Ramadan will likely begin between early February and early March in 2027 and will last for 29 or 30 days. Get more advice when you arrive from your tour guide, hotel or business contacts."]},{"k":"p","s":["During this time, it may cause offence if you:"]},{"k":"li","s":["eat, drink, smoke or chew gum in public in the daytime, including in your car"]},{"k":"li","s":["play loud music or dance"]},{"k":"li","s":["swear in public"]},{"k":"p","s":["You should also:"]},{"k":"li","s":["check opening hours of shops and restaurants"]},{"k":"li","s":["be aware that if hotels and restaurants are providing food or drink in fasting hours, they may separate you from Islamic guests, for example with screens"]},{"k":"li","s":["follow local dress codes – clothing that does not meet local dress codes may cause more offence at this time"]},{"k":"li","s":["be aware that driving may be erratic, particularly when people are trying to get home at dusk"]},{"k":"li","s":["be patient and show tolerance – fasting can cause tiredness, particularly during the late afternoon and early evening"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["It is illegal not to carry some form of photographic ID in Turkey. Always carry your passport or residence permit. In some busy areas, especially Istanbul, the authorities may stop people for ID checks. There are also several police checkpoints on main roads across Turkey. Cooperate with officials conducting checks."]},{"k":"hs","s":["Children and accommodation"]},{"k":"p","s":["There are some reports of hotels refusing to check-in children aged 17 and under who are not accompanied by a parent or guardian, unless written parental consent has been provided (and in some cases notarised). Check with your accommodation provider in advance."]},{"k":"hs","s":["Dress code"]},{"k":"p","s":["Dress modestly if you’re visiting a mosque or a religious shrine to avoid causing offence."]},{"k":"hs","s":["Personal injury claims"]},{"k":"p","s":["There are reports of tourists being encouraged to submit a claim for personal injury if they have experienced gastric illness in Turkey. Find out what you can do if you have suffered a personal injury on the ",["Citizens Advice website","https://www.citizensadvice.org.uk/law-and-courts/legal-system/personal-injury/personal-injuries/"],". Only make a claim if you have genuinely suffered from injury or illness. If you make a false or fraudulent claim, you may face legal proceedings in the UK or Turkey."]},{"k":"hs","s":["Smoking bans"]},{"k":"p","s":["Smoking is illegal on public transport and in all indoor workplaces and public places. Smoking is restricted in some outdoor areas where cultural, artistic, sports or entertainment activities are held."]},{"k":"hs","s":["Illegal drugs"]},{"k":"p","s":["Illegal drugs, including cannabis, carry severe penalties. You should expect a long prison sentence of 4 to 24 years and heavy fines for possessing, using or smuggling illegal drugs, including when transiting through airports."]},{"k":"p","s":["Airports in Turkey have excellent technology and security for detecting illegal items. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["Stray dogs"]},{"k":"p","s":["Most towns and cities have stray dogs. Packs congregate in parks and wastelands and can be aggressive. Take care and do not approach stray dogs. If you’re bitten, get medical advice immediately. Rabies and other animal borne diseases are present in Turkey."]},{"k":"hs","s":["Sale of antiquities"]},{"k":"p","s":["Buying or exporting antiquities is illegal. You could be fined and receive a prison sentence of 5 to 12 years. Some historical items found at local markets and in antique shops can be sold within Turkey but are illegal to export. Confirm the status of antique items before you buy them."]},{"k":"hs","s":["Using cameras"]},{"k":"p","s":["Do not take photographs of or near military or official installations. Ask for permission before photographing people."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex sexual activity is legal in Turkey. However, some parts of the country are socially conservative and public displays of affection may attract unwanted attention. Same-sex relationships are not legally recognised."]},{"k":"p","s":["Since 2015, authorities have banned or dispersed Pride events. Anti-LGBT+ statements by senior public figures have increased in recent years, and restrictions on LGBT+ organisations have increased. Turkish authorities have carried out operations against LGBT+ organisations and activists across the country."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Comments about the nation and flag"]},{"k":"p","s":["It is illegal to insult the Turkish nation or the national flag. Insulting the President or the founder of the Turkish Republic, Mustafa Kemal Atatürk, is also a criminal offence. These laws can apply to comments or images online no matter where you were or when you posted them. Defacing Turkish banknotes is also illegal. Offences under these laws are punishable by a prison sentence of between 6 months and 3 years."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"hs","s":["Extreme sports"]},{"k":"p","s":["If you do an extreme sport, check that adequate safety precautions are in place. British nationals have been injured and killed doing extreme sports. Only use reputable operators. Make sure you are given full instructions and training before your activity. Make sure your travel insurance covers you for all activities you do. Always read the details of your insurance cover, especially the small print and exclusions on your policy."]},{"k":"hs","s":["Paragliding"]},{"k":"p","s":["Paragliding is an extreme sport and carries the risk of serious injury or death. British nationals have died or been seriously injured whilst paragliding in Turkey."]},{"k":"p","s":["Make sure you are given full instructions and training before your activity."]},{"k":"p","s":["If you are near where paragliding activities take place, be aware that the landing area may be in a public area. Keep a reasonable distance from potential landing zones for your personal safety."]},{"k":"hs","s":["Quad biking and mopeds"]},{"k":"p","s":["Quad biking is an extreme sport and carries the risk of serious injury or death. You need specific travel insurance to cover quad biking. Always read the details of your insurance cover, especially the small print and exclusions on your policy."]},{"k":"p","s":["Make sure you are given full instructions and training before your activity."]},{"k":"p","s":["Insurance sold by the hire company usually only provides third party insurance. It’s likely you will be charged for any damage to the rental vehicle and you may face arrest if you do not pay."]},{"k":"p","s":["If you hire a moped you need a valid driving licence with at least category A1 - ‘light motorcycle’. Make sure the vehicle is in good condition. Drivers and passengers must wear helmets. Failure to do so may invalidate your insurance. If police stop you, they will fine you and take your licence."]},{"k":"hs","s":["Jeep safaris"]},{"k":"p","s":["Jeep safaris can be dangerous - there have been a number of reported accidents in recent years. If you join a jeep safari, use a reputable company who have adequate health and safety procedures and equipment. Always check that activities are covered by your insurance."]},{"k":"hs","s":["Water sports"]},{"k":"p","s":["Book activities at a licensed water sports centre and before you start:"]},{"k":"li","s":["make sure the paperwork is completed"]},{"k":"li","s":["ask for a safety demonstration"]},{"k":"li","s":["make sure you know how to call for help"]},{"k":"hs","s":["Swimming and beaches"]},{"k":"p","s":["Every year, people drown in the sea and in swimming pools in Turkey. Always supervise children, even if they can swim or there is a lifeguard present."]},{"k":"p","s":["Take care when swimming in the sea. Some beaches may have strong undercurrents."]},{"k":"p","s":["Hidden rocks or shallow depths can cause serious injury or death. Do not dive into unknown water."]},{"k":"p","s":["Follow local advice if jellyfish or urchins are present. See further information on the ",["Turkish Marine Research Foundation’s page.","https://tudav.org/en/our-fields/marine-biodiversity/biological-invasions/press-release-warning-for-jellyfish-in-the-mediterranean-sea/"]]},{"k":"p","s":["Many beaches have a flag system. Make sure you understand the system and follow any warnings (a red flag means you must not enter the water). Follow instructions from lifeguards. Take extra care and seek local advice if there are no lifeguards, flags, or signs."]},{"k":"p","s":["See further tips on ",["ABTA’s swim safe pages","https://www.abta.com/tips-and-advice/staying-safe-on-holiday/swim-safe"]," and ",["Water Safety on Holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Turkey, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You need a ",["1968 international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," or a UK driving licence notarised in Turkish to drive in Turkey. The 1949 IDP is not accepted any more. You cannot buy an IDP outside the UK, so get one before you travel. You must also ",["carry a green card","https://www.gov.uk/vehicle-insurance/driving-abroad"]," to show you have third party insurance."]},{"k":"p","s":["If you bring a vehicle registered in another country into Turkey, observe the Turkish customs regulations. Check if you need a ",["UK sticker to drive your car outside the UK","https://www.gov.uk/displaying-number-plates/flags-identifiers-and-stickers"],"."]},{"k":"hs","s":["Driving conditions"]},{"k":"p","s":["Take care when travelling by road, particularly at night. Approach checkpoints slowly and follow the instructions of security personnel. Roads between major cities are generally in excellent condition, but the road surface can be poor in remote areas. Accidents are common – mainly due to poor or reckless driving."]},{"k":"p","s":["It is illegal to ride without a helmet on motorcycles and mopeds. You may get a severe fine if you are not wearing a helmet."]},{"k":"p","s":["Do not drink and drive. The police fine drunk drivers and they could confiscate your licence for 6 months."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["Many parts of Turkey regularly experience earthquakes and tremors. These can be high magnitude, cause damage to infrastructure, and pose a risk to life."]},{"k":"p","s":["A 6.2-magnitude earthquake which occurred in the Sea of Marmara in April 2025, was felt strongly in Istanbul. Be aware of the risk of aftershocks. See ",["Turkey’s Disaster and Emergency Management Authority’s (AFAD) earthquake page","https://deprem.afad.gov.tr/last-earthquakes"]," for the latest information about seismic activity in Turkey."]},{"k":"p","s":["Follow advice from local authorities, tour operators and accommodation providers. See the US Federal Emergency Management Agency guidance about what to do ",["before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"hs","s":["Extreme temperatures"]},{"k":"p","s":["Extreme temperatures can affect many areas of Turkey over the summer months."]},{"k":"p","s":["The NHS has information on ",["how to cope in hot weather","https://www.nhs.uk/live-well/seasonal-health/heatwave-how-to-cope-in-hot-weather/"],"."]},{"k":"hs","s":["Wildfires"]},{"k":"p","s":["Wildfires happen frequently in Turkey during summer."]},{"k":"p","s":["You could get a fine or prison sentence for lighting a fire of any kind or discarding cigarettes in risk areas such as woodland. Look out for signs that tell you fires, barbeques, and smoking are prohibited."]},{"k":"p","s":["If there is a wildfire in your area, local authorities may tell you to leave your accommodation. Follow the directions of local authorities."]},{"k":"p","s":["If you see a wildfire, call emergency services on 112."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["Severe rainstorms can cause flooding and landslides across Turkey, damaging roads and bridges. Some routes may become impassable, making it difficult to travel and reducing essential services."]},{"k":"p","s":["If you’re in an affected area:"]},{"k":"li","s":["monitor local media"]},{"k":"li","s":["follow instructions of local authorities, including evacuation orders"]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Turkey. It only covers regions where FCDO has specific advice."]},{"k":"p","s":["You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/turkey"],"."]},{"k":"h","s":["Turkey-Syria border"]},{"k":"p","s":["FCDO advises against all travel within 10km of the Turkey-Syria border."]},{"k":"p","s":["Fighting in Syria continues in areas close to the Turkish border and there is a heightened risk of terrorism in the region. See ",["Terrorism","https://www.gov.uk/foreign-travel-advice/turkey/safety-and-security#terrorism"],"."]},{"k":"p","s":["Due to the ongoing conflict in Syria, roads in Hatay Province leading towards the border may be closed at short notice."]},{"k":"h","s":["Hakkari province, south-east Turkey"]},{"k":"p","s":["In Hakkari province you must get permission from the local Governor’s Office to visit areas near the border with Iraq and Iran. If visiting with a travel agent or tour group, confirm with them whether you need an individual permit. Keep up to date with local media and follow the advice of the local authorities."]},{"k":"h","s":["Mount Ararat, eastern Turkey"]},{"k":"p","s":["Mount Ararat, in Ağrı Province, is a special military zone. You must have permission from the Doğubayazıt government office and pay a fee. If visiting with a travel agent or tour group, confirm with them whether you need an individual permit."]},{"k":"p","s":["Take extra care if you’re travelling to this area. Keep up to date with local media and follow the advice of the local authorities."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 112 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company promptly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Turkey","https://www.travelhealthpro.org.uk/country/227/turkey#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Turkey","https://www.travelhealthpro.org.uk/country/227/turkey"],"."]},{"k":"p","s":["Altitude sickness is a risk in parts of Turkey. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["British prescriptions are not accepted in pharmacies in Turkey. In some cases, you may be able to liaise with Turkish hospitals and your GP to arrange for a Turkish prescription for the equivalent medicine."]},{"k":"p","s":["Some common medicines are controlled in Turkey. See ",["more information about the documentation you need","https://gumrukrehberi.gov.tr/Public/Index"],", or contact the nearest Turkish embassy or consulate."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Turkey"]},{"k":"p","s":["FCDO has a list of ",["medical providers in Turkey","https://www.gov.uk/government/publications/turkey-list-of-medical-practitioners"]," where some staff will speak English."]},{"k":"p","s":["The European Health Insurance Card and Global Health Insurance card are not valid in Turkey."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Medical tourism"]},{"k":"p","s":["Medical tourism is when people travel to have medical, surgical or dental treatment abroad. Cosmetic surgery, dental procedures and cardiac surgery are the most common procedures for medical tourists."]},{"k":"p","s":["The standard of medical facilities and available treatments can vary widely globally and also within countries. We are aware of 7 British nationals having died in Turkey in 2025 following medical procedures. Some British nationals have also experienced complications and needed further treatment or surgery following their procedure."]},{"k":"p","s":["If you are considering travelling to Turkey for medical, surgical or dental treatment:"]},{"k":"li","s":["discuss plans with your UK doctor, dentist or clinician before going ahead"]},{"k":"li","s":["do your own research - private companies have a financial interest in booking your treatment and their literature should not be your only source of information"]},{"k":"p","s":["See more details about the ",["risks of going abroad for elective surgery","https://www.gov.uk/guidance/in-hospital-abroad#going-abroad-for-medical-treatment-and-planned-elective-surgery"],"."]},{"k":"p","s":["The Turkish Ministry of Health provides a list of its approved medical providers on the ",["HealthTurkiye website","https://www.healthturkiye.com/"],"."]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) does not give any endorsement of the competence or suitability of any practitioner or facility."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Turkey"]},{"k":"p","s":["Telephone: 112 (ambulance, fire, police)"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find?serviceType=lawyers&country=Turkey"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find?country=Turkey&serviceType=funeralDirectors"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find?country=Turkey&serviceType=translatorsInterpreters"]]},{"k":"li","s":["dealing with a ",["death in Turkey","https://www.gov.uk/guidance/what-to-do-after-a-british-person-dies-in-turkey"]]},{"k":"li","s":["being ",["arrested in Turkey","https://www.gov.uk/government/publications/turkey-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["If you are ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/turkey/british-embassy-ankara"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/turkey/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Turkey","https://www.gov.uk/government/publications/overseas-business-risk-turkey"]," on how to manage political, economic, and business security-related risks."]}],"chars":30041,"change":"Updated information about regional tensions (See ‘Warnings and insurance’ page)."},"https://theconversation.com/cop31-the-world-is-heading-for-climate-overshoot-the-un-summit-must-start-planning-for-what-comes-next-296769":{"r":"conversation","at":"2026-11-19T19:38Z","sha":"1d5eddd66da491761181200867061ad18671ca895d1637aa1ec69f409a3bc7b1","read":"https://theconversation.com/cop31-the-world-is-heading-for-climate-overshoot-the-un-summit-must-start-planning-for-what-comes-next-296769","bytes":183390,"x":"fulltext v1","title":"Cop31: the world is heading for climate ‘overshoot’ – the UN summit must start planning for what comes next","by":[{"n":"Michael Jacobs","r":"Professor of Political Economy, University of Sheffield"}],"pub":"2026-11-19T12:21:46Z","mod":"","blocks":[{"k":"p","s":["A surprising thing has happened at the UN climate conference, ",["Cop31","https://theconversation.com/topics/cop31-129714"],", as it gears up to its conclusion in Antalya, Turkey. Negotiators are discussing how to cool the planet."]},{"k":"p","s":["You might think this should not be surprising, but how to respond to the latest climate science was not on the agenda when the meeting started. Now, the summit’s latest ",["draft decision","https://unfccc.int/documents/665726"]," explicitly recognises a role for carbon dioxide removal (CDR) alongside deep emissions cuts. This is a significant shift, driven by pressure from some of the countries most vulnerable to climate change – the small island states – in response to two alarming scientific reports in the last month."]},{"k":"p","s":["The World Meteorological Organization has ",["confirmed","https://wmo.int/media/news/state-of-climate-2026-gives-new-meaning-phrase-charts"]," that the ",["rate at which the Earth is heating up is accelerating","https://www.carbonbrief.org/pace-of-global-warming-has-nearly-doubled-since-2015-study-says"],". One reason is the planet is becoming less “reflective”: the loss of ice and snow, changes in cloud formation and (paradoxically) reductions in atmospheric pollution means that more solar radiation is being absorbed rather than reflected into space."]},{"k":"p","s":["The result is that the Paris Agreement goal of limiting warming to 1.5°C will not be met. There’s a new term for this new warming trajectory: “overshoot”. As a ",["United Nations Environment Programme (Unep) report","https://www.unep.org/en/publications/report/emissions-gap-report-2026"]," explains, the best we can hope for now is to exceed 1.5°C but then limit the extent of the overshoot, peaking emissions as soon as possible and then returning to 1.5°C later in the century."]},{"k":"p","s":["Unfortunately, Unep also notes that this may be easier said than done. The longer temperatures remain above 1.5°C, the greater the risk of triggering irreversible changes to systems such as polar ice sheets and glaciers, ocean currents and the Amazon rainforest, which could make returning to lower temperatures impossible."]},{"k":"h","s":["Beyond cutting emissions"]},{"k":"p","s":["Up until now we have thought there were basically two responses to global heating. We needed to cut emissions (mitigation), and cope with the warming we experienced (adaptation). But overshoot means that achieving net zero emissions is not enough. By the time we get there the temperature will be too high."]},{"k":"p","s":["Overshoot will require two other kinds of response. As well as cutting the flow of greenhouse gases into the atmosphere, we can physically take them out, a process known as carbon dioxide removal or CDR."]},{"k":"p","s":["And we will also need to consider different ways to increase the planet’s reflectivity. These include ",["limiting aircraft contrails","https://drawdown.org/explorer/reduce-airplane-contrails"]," (which trap heat), expanding the white surface areas of the earth (both buildings and crops), or making glaciers more stable. It could potentially include various methods of “ ",["solar radiation management","https://iere.org/what-is-solar-radiation-management/"],"”, such as brightening clouds over the oceans, or injecting reflective aerosols into the stratosphere. If any of these “climate cooling” technologies could help bring temperatures down, they need much more carefully governed research."]},{"k":"p","s":["Removing carbon dioxide from the atmosphere is not the same as carbon capture and storage (CCS), which refers to the capture of emissions from industrial plants before they reach the atmosphere. In all net zero scenarios ",["CCS is needed","https://www.ipcc.ch/report/ar6/wg3/chapter/chapter-3/"]," to deal with the residual emissions of fossil fuels. But we now know CDR is going to be required as well – first alongside emissions reduction, to slow warming down, and then to return the global temperature to a safer level."]},{"k":"p","s":["There are ",["various potential removal methods","https://www.carbonbrief.org/qa-the-current-state-of-carbon-dioxide-removal-around-the-world"],". Some are familiar and uncontroversial, though not yet being done at anything like the required scale. These are natural processes such as tree-planting, restoring ecosystems and improving carbon in soils."]},{"k":"p","s":["Other “novel” forms of CDR are still in development. Carbon uptake methods in the oceans include ",["enhancing the ocean’s alkalinity","https://oceanvisions.org/our-strategy/remove/ocean-alkalinity-enhancement/"]," and the ",["fertilisation of phytoplankton","https://www.ciwem.org/news/how-fertilising-the-oceans-with-iron-could-help-fight-the-climate-crisis"]," by adding iron. On land, enhanced natural processes include adding charcoal to soils (“ ",["biochar","https://www.carbonbrief.org/explainer-10-ways-negative-emissions-could-slow-climate-change#biochar"],"”), and accelerating the creation of carbonates from ",["rock weathering","https://www.carbonbrief.org/explainer-10-ways-negative-emissions-could-slow-climate-change#enhanced%20weathering"],"."]},{"k":"p","s":["There are also more technological interventions. These include “bioenergy with carbon capture and storage” ( ",["Beccs","https://www.carbonbrief.org/explainer-10-ways-negative-emissions-could-slow-climate-change#beccs"],"), in which biomass is burned for energy and the emissions captured and stored underground; and ",["“direct air capture”","https://www.cleanenergywire.org/factsheets/qa-dac"],", the removal of CO₂ from the air with advanced machines."]},{"k":"p","s":["All of these methods are now being piloted, but remain expensive. Some of them also raise environmental risks: before any could be used at significant scale, countries would need to be sure that they would not have negative side-effects. In turn that means the world needs to think seriously about their governance."]},{"k":"h","s":["The politics of cooling the planet"]},{"k":"p","s":["But there is currently no place for such talks. Neither novel methods of carbon dioxide removal, nor increasing the earth’s reflectivity, are formally part of the Cop negotiations or indeed any other UN policy process."]},{"k":"p","s":["This is because many countries have believed that any discussion of these would take the pressure off emissions reduction. They have been supported in this view by some of the larger ",["climate NGOs","https://www.foei.org/reaction-ipcc-synthesis/"],", who have not wanted anything to distract from their campaign against fossil fuels."]},{"k":"p","s":["But the world has changed. Climate science says emissions reduction on its own can no longer keep us on a safe climate pathway. This surely makes blanket opposition to novel CDR and cooling methods untenable. Governments need to be scaling up research into these methods and considering their governance. At the very least, they should be talking about them."]},{"k":"p","s":["This is why the latest moves at Cop31 are so important. At this point it is not clear whether countries will agree to a statement on how to respond to overshoot. Some are still opposed. But if the final text does acknowledge that active cooling will be needed, it will mark the beginning of a new era in climate action."]}],"chars":5689},"https://theconversation.com/13-years-of-waiting-for-gta-vi-what-the-hype-says-about-how-we-consume-296878":{"r":"conversation","at":"2026-11-19T19:38Z","sha":"29d589fb4558f3aebe5cdd4a404ee7dde35efb8727ec009faa09e8bd3ee0df9e","read":"https://theconversation.com/13-years-of-waiting-for-gta-vi-what-the-hype-says-about-how-we-consume-296878","bytes":183113,"x":"fulltext v1","title":"13 years of waiting for GTA VI: what the hype says about how we consume","by":[{"n":"Farhan Mutaqin","r":"PhD Researcher, University of Edinburgh"},{"n":"Almukantar Fikriansyah","r":"MSc Marketing (cand.) at The University of Edinburgh"},{"n":"Jusuf Ariz Wahyuono","r":"Research Staff, Universitas Gadjah Mada"}],"pub":"2026-11-19T08:00:55Z","mod":"","blocks":[{"k":"p","s":["Thirteen years since Grand Theft Auto V (GTA V) was released, its long-awaited successor, ",["Grand Theft Auto VI (GTA VI)","https://www.rockstargames.com/VI"],", finally launches today, 19 November 2026."]},{"k":"p","s":["Even before its launch, GTA VI has already become ",["a global phenomenon","https://theconversation.com/how-gta-6-became-a-global-phenomenon-we-cant-ignore-291043"],". Its first trailer, released in December 2023, attracted more than ",["90 million YouTube views within 24 hours","https://www.guinnessworldrecords.com/world-records/758375-most-viewed-youtube-video-in-24-hours-non-music"],"."]},{"k":"p","s":["It broke the Guinness World Record for the most-viewed non-music video in 24 hours, ",["while sparking fan theories, online debates and a wave of social media content","https://blog.youtube/culture-and-trends/grand-theft-auto-breaks-record/"]," that kept the hype alive."]},{"k":"p","s":["In GTA VI, players will follow Jason Duval and Lucia Caminos, a criminal duo whose story unfolds in Vice City, a fictional city inspired by Miami, and the fictional state of Leonida, based on Florida. The game is expected to explore familiar GTA territory, including drugs, gang rivalries and organised crime."]},{"k":"p","s":["Why are millions of people so excited about a game that has taken more than a decade to make?"]},{"k":"p","s":["Read more: ",["How GTA 6 became a global phenomenon we can’t ignore","https://theconversation.com/how-gta-6-became-a-global-phenomenon-we-cant-ignore-291043"]]},{"k":"h","s":["The game everyone is waiting for"]},{"k":"p","s":["Since its debut in 1997, ",["the GTA","https://www.imdb.com/list/ls072970193/"]," franchise has evolved through several generations of gaming consoles, selling more than ",["475 million copies worldwide","https://www.shanethegamer.com/research/gta-sales-statistics/"],"."]},{"k":"p","s":["Because of its depiction of ",["violence","https://www.semanticscholar.org/paper/Growing-Up-with-Grand-Theft-Auto%3A-A-10-Year-Study-Coyne-Stockdale/3e286c87dba00a1fbbad94b138d2df25786f28e7"],", GTA has always been controversial. The debate intensified when the games were cited as an influence in a case involving an ",["eight-year-old boy in Louisiana","https://edition.cnn.com/2013/08/25/us/louisiana-boy-kills-grandmother"]," who fatally shot his grandmother. Its adult themes and sexually explicit content are likely to spark controversy again when GTA VI arrives"]},{"k":"p","s":["On the technical side, Rockstar, the studio behind the franchise, helped redefine gaming with its open-world “sandbox” design. Players could explore freely and take part in ",["activities that resemble everyday life","https://www.researchgate.net/publication/382940992_Grand_Theft_Auto_An_Influential_Gaming_Phenomenon_and_Its_Impact_on_Pop_Culture"],"."]},{"k":"p","s":["The earliest games focused mainly on car chases, shootouts and destruction, viewed from above. GTA III changed the formula by introducing a fully 3D open world. Later titles expanded player freedom even further, allowing them to buy properties, run businesses and explore beyond the main storyline."]},{"k":"p","s":["As the successor to GTA V, widely regarded as a benchmark for open-world gaming, GTA VI faces enormous pressure to raise the bar. Two delays have only fuelled ",["players’ curiosity","https://weazelreport.com/en/gta-6-delays-nobodys-mad/"],", suggesting that Rockstar wants more time to get the details right."]},{"k":"p","s":["In a way, waiting has become part of the fun. This reflects an idea from economist ",["George Loewenstein","https://www.researchgate.net/publication/375206640_Anticipation_and_the_Valuation_of_Delayed_Consumption"],": looking forward to something can itself be a source of enjoyment."]},{"k":"p","s":["Rockstar’s marketing strategy also echoes marketing professor ",["Stephen Brown’s","https://www.researchgate.net/publication/256014242_Torment_Your_Customers_They%27ll_Love_It"]," argument that brands can build excitement by teasing customers and keeping them waiting."]},{"k":"p","s":["Nostalgia adds another layer. Many players who first explored GTA: Vice City in 2002 are now adults, eager to revisit its neon-lit streets. For them, GTA VI is not just a new game but a return to a familiar virtual world."]},{"k":"p","s":["Read more: ",["Grand Theft Auto: players are voting, debating, protesting and making political decisions","https://theconversation.com/grand-theft-auto-players-are-voting-debating-protesting-and-making-political-decisions-292562"]]},{"k":"h","s":["With great expectations comes great pressure to deliver"]},{"k":"p","s":["Once GTA VI hits the shelves, one big question will remain: can it live up to years of hype and sky-high expectations?"]},{"k":"p","s":["The excitement has already fuelled a massive wave of user-generated content, from YouTube trailer reactions (the official trailer has surpassed ",["300 million views","https://www.youtube.com/watch?v=QdBZY2fkU-0"],", alongside more than a million comments) to ",["Reddit discussions","https://www.reddit.com/r/GTA6/"],", fan theories and memes across social media."]},{"k":"p","s":["GTA VI is also projected to attract ",["15 million digital pre-orders","https://www.vice.com/en/article/how-many-people-pre-ordered-gta-6/"]," across PlayStation 5 and Xbox Series X|S, potentially generating US$1.4 billion. If realised, this would set a new pre-order record. The figures point to strong ",["brand attachment","https://link.springer.com/article/10.1057/s41262-022-00279-5"],", with millions of fans willing to invest their time, money and patience before the game is even released."]},{"k":"p","s":["By the time players return to Vice City, many will already feel familiar with its streets. But whether they enjoy the game will depend not only on its quality, but also on how well it matches their expectations. This is known as ",["expectation-disconfirmation theory","https://link.springer.com/article/10.1007/s11747-024-01078-x"],": the higher the expectations, the harder it is for a product to satisfy consumers."]},{"k":"p","s":["The gaming industry has seen what happens when a major release falls short. Cyberpunk 2077, one of the most anticipated games of 2020, launched with widespread technical problems. Sony removed it from the PlayStation Store and offered refunds after the game ran poorly on the PS4 and Xbox One."]},{"k":"p","s":["For Rockstar, the hype surrounding GTA VI is both an opportunity and a risk. The game could become another landmark release, but failing to meet expectations could trigger an equally massive backlash. After all, this is a blockbuster reportedly costing up to ",["US$2 billion","https://emeraldbook.org/news/aug-0826/"]," to develop and market."]},{"k":"p","s":["Read more: ",["Grand Theft Auto 6 could make US$3–5 billion in the next week. Here’s how games make so much money","https://theconversation.com/grand-theft-auto-6-could-make-us-3-5-billion-in-the-next-week-heres-how-games-make-so-much-money-290719"]]},{"k":"h","s":["A new era for gaming consoles?"]},{"k":"p","s":["GTA VI promises a technically ambitious gaming experience, including a ",["highly dynamic weather system that mirrors the real world","https://sea.ign.com/grand-theft-auto-vi-rumored-title/252036/gta-6-gets-new-screenshots-highlighting-leonidas-dynamic-weather"],". But it is expected to run at only ",["30fps","https://www.vice.com/en/article/gta-6-ps5-pro-framerate-explained/"]," for both consoles, even though modern games run at 60fps."]},{"k":"p","s":["Does this mean we need a new generation of gaming consoles console?"]},{"k":"p","s":["From a business standpoint, however, GTA VI’s release does not necessarily mean a new generation of gaming consoles is just around the corner. A study of the US console market from 1993 to 2004 by marketing researchers ",["Jeroen Binken and Stefan Stremersch","https://personal.eur.nl/stremersch/artikels/2009%20-%20JM%20-%20The%20Effect%20of%20Superstar%20Software%20on%20Hardware%20Sales%20in%20System%20Markets%28JM%20Version%29.pdf"]," found that the release of a “superstar” game could increase hardware sales by an average of 14% during the launch month and the following five months."]},{"k":"p","s":["Both ",["Sony","https://gamerant.com/playstation-6-ps6-price-investments-2027/"]," (with the PS6) and ",["Microsoft","https://news.xbox.com/en-us/2026/03/11/project-helix-building-next-generation-of-xbox/"]," (with Xbox Helix) have confirmed that next-generation consoles are in development. However, firm release dates remain unclear. The industry is also facing a ",["global chip supply shortage","https://www.cnbc.com/2026/01/26/memory-chip-shortage-synopsys-lenovo-ai-data-centers.html"]," driven partly by growing demand from data centres, artificial intelligence and electric vehicles."]},{"k":"p","s":["More broadly, GTA VI highlights how major game publishers manage financial risks. In his research on the blockbuster “AAA” gaming industry, ",["David Nieborg","https://dare.uva.nl/id/51d3566b-0af3-459f-8606-aaa427936ae4"],", a media studies scholar at the University of Toronto Scarborough, explains why studios increasingly rely on established franchises to reduce uncertainty in an unpredictable market."]},{"k":"p","s":["GTA VI shows just how powerful an established brand can be. Beyond the hype surrounding its release, the phenomenon reveals something about modern consumer behaviour: consumption does not always begin when we buy or use a product. Sometimes, it starts much earlier, when we begin looking forward to it."]}],"chars":6435}};
